from AlgorithmImports import *
from collections import deque
from datetime import timedelta, datetime


class SpyLongCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        spy_security = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False
        )
        spy_security.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = spy_security.Symbol

        option_security = self.AddOption("SPY", Resolution.Minute)
        option_security.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=730))
        )
        self.option_symbol = option_security.Symbol

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None
        self.pending_signal = False

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        end_time = bar.EndTime.time()

        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0

        self.closes.append(float(bar.Close))

        if len(self.closes) >= 20:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
            current_slow = sum(self.closes) / 20.0

            bullish_cross = (
                previous_fast is not None
                and previous_slow is not None
                and previous_fast <= previous_slow
                and current_fast > current_slow
            )

            if (
                bullish_cross
                and datetime.strptime("09:45", "%H:%M").time() <= end_time
                <= datetime.strptime("14:30", "%H:%M").time()
            ):
                self.pending_signal = True

    def OnData(self, slice):
        current_date = self.Time.date()

        if self.held_contract is not None:
            expiry_date = self.held_contract.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self.SubmitExit("expiration")
            elif self.IsExpirationEve(current_date, expiry_date):
                if self.Time.hour == 15 and self.Time.minute == 45:
                    self.SubmitExit("expiration-eve")
            else:
                self.CheckProfitTarget(slice)

        if (
            self.pending_signal
            and current_date != self.blocked_entry_date
            and self.held_contract is None
            and not self.IsEntryOrderOpen()
        ):
            self.pending_signal = False
            self.TryEnter(slice)

    def TryEnter(self, slice):
        underlying_bar = slice.Bars.get(self.spy)
        if underlying_bar is None:
            self.Debug("Skipped entry: SPY price unavailable")
            return

        current_price = float(underlying_bar.Close)
        chains = list(slice.OptionChains.Values)

        if not chains:
            self.Debug("Skipped entry: option chain unavailable")
            return

        contracts = []
        for chain in chains:
            contracts.extend(list(chain))

        current_date = self.Time.date()
        eligible = [
            contract for contract in contracts
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        ]

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 days out")
            return

        expiration = min(contract.Expiry.date() for contract in eligible)

        candidates = [
            contract for contract in eligible
            if (
                contract.Expiry.date() == expiration
                and contract.Right == OptionRight.Call
                and contract.Strike >= current_price * 1.01
            )
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, strike {1}, expiry {2}".format(
                selected.Symbol, selected.Strike, expiration
            )
        )

    def CheckProfitTarget(self, slice):
        if self.held_contract is None or self.entry_price is None:
            return

        quote = slice.QuoteBars.get(self.held_contract.Symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("profit-target")

    def SubmitExit(self, reason):
        if self.held_contract is None:
            return

        if self.IsExitOrderOpen():
            if reason == "expiration":
                self.exit_ticket.Cancel("Expiration liquidation")
            else:
                return

        quantity = self.Portfolio[self.held_contract.Symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_contract.Symbol,
            -quantity
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_contract.Symbol, reason
            )
        )

    def IsEntryOrderOpen(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def IsExitOrderOpen(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def IsExpirationEve(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)

        while candidate >= current_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                return current_date == candidate
            candidate -= timedelta(days=1)

        return False

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_contract = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.entry_ticket = None
                    self.Debug(
                        "Entry filled: {0} at {1}".format(
                            self.held_contract, self.entry_price
                        )
                    )
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.Debug("Entry order did not fill")
                    self.entry_ticket = None

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug("Exit filled: {0}".format(order_event.Symbol))
                    self.exit_ticket = None
                    self.held_contract = None
                    self.entry_price = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected
                ):
                    self.exit_ticket = None

    def OnAssignmentOrder(self, assignment_event):
        self.Debug(
            "Unexpected option exercise or assignment: {0}".format(
                assignment_event
            )
        )

