from datetime import datetime, timedelta

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Orders import OrderStatus
from QuantConnect.Securities import DataNormalizationMode, OptionRight, Resolution


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_symbol = self.option.Symbol

        self.closes = []
        self.bucket_date = None
        self.bucket_start_minute = None
        self.bucket_bars = []
        self.bucket_valid = True

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.held_symbol is not None:
            expiry_date = self.held_symbol.ID.Date.date()

            if current_date >= expiry_date:
                self.blocked_entry_date = current_date
                self._submit_exit("expiration liquidation")
            else:
                previous_trading_day = self._previous_trading_day(expiry_date)
                if (
                    current_date == previous_trading_day
                    and self.Time.hour == 15
                    and self.Time.minute >= 45
                ):
                    self._submit_exit("pre-expiration time stop")
                else:
                    self._evaluate_profit_target(slice)

        if self.held_symbol is not None:
            if self.Portfolio[self.held_symbol].Quantity == 0:
                if not self._is_open(self.exit_ticket):
                    self.held_symbol = None
                    self.entry_price = None

        if self.spy not in slice.Bars:
            return

        spy_bar = slice.Bars[self.spy]
        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        timestamp = bar.Time
        bar_date = timestamp.date()
        minute_of_day = timestamp.hour * 60 + timestamp.minute

        regular_start = 9 * 60 + 30
        regular_end = 16 * 60

        if minute_of_day < regular_start or minute_of_day >= regular_end:
            return

        bucket_start = regular_start + ((minute_of_day - regular_start) // 5) * 5

        if (
            self.bucket_date is None
            or bar_date != self.bucket_date
            or bucket_start != self.bucket_start_minute
        ):
            self._finalize_bucket(slice)

            self.bucket_date = bar_date
            self.bucket_start_minute = bucket_start
            self.bucket_bars = []
            self.bucket_valid = True

        expected_minute = self.bucket_start_minute + len(self.bucket_bars)

        if minute_of_day != expected_minute:
            self.bucket_valid = False

        if len(self.bucket_bars) < 5:
            self.bucket_bars.append(bar)

        if len(self.bucket_bars) == 5:
            self._finalize_bucket(slice)
            self.bucket_date = None
            self.bucket_start_minute = None
            self.bucket_bars = []
            self.bucket_valid = True

    def _finalize_bucket(self, slice: Slice):
        if (
            self.bucket_date is None
            or len(self.bucket_bars) != 5
            or not self.bucket_valid
        ):
            return

        close = float(self.bucket_bars[-1].Close)
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0

        self.closes.append(close)

        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        if previous_fast is None or previous_slow is None:
            return

        bar_end_minute = self.bucket_start_minute + 5

        if not (9 * 60 + 45 <= bar_end_minute <= 14 * 60 + 30):
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if bullish_cross:
            self._evaluate_entry(slice, close)

    def _evaluate_entry(self, slice: Slice, spy_price: float):
        current_date = self.Time.date()

        if current_date == self.blocked_entry_date:
            return

        if self.held_symbol is not None:
            return

        if self._is_open(self.entry_ticket) or self._is_open(self.exit_ticket):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)

        eligible = [
            contract for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        ]

        if not eligible:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in eligible
        )

        strike_floor = spy_price * 1.01

        candidates = [
            contract for contract in eligible
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= strike_floor
            )
        ]

        if not candidates:
            self.Debug(
                "Skipped call selection: no qualifying call at selected expiration."
            )
            return

        selected = min(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

        self.Debug(
            "Entry submitted: {} expiry={} strike={}".format(
                selected.Symbol,
                selected.Expiry.date(),
                selected.Strike
            )
        )

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._is_open(self.exit_ticket):
            return

        quote = slice.QuoteBars.get(self.held_symbol)
        if quote is None or quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self._is_open(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )

        self.Debug(
            "Exit submitted: {} reason={}".format(self.held_symbol, reason)
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled
            ):
                if order_event.FillQuantity > 0:
                    self.held_symbol = self.entry_ticket.Symbol
                    self.entry_price = float(order_event.FillPrice)
                    self.Debug(
                        "Entry filled: {} price={}".format(
                            self.held_symbol,
                            self.entry_price
                        )
                    )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Margin ולא
            ):
                self.Debug(
                    "Entry order did not fill: {} status={}".format(
                        self.entry_ticket.Symbol,
                        order_event.Status
                    )
                )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {} price={}".format(
                    self.exit_ticket.Symbol,
                    order_event.FillPrice
                )
            )

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.blocked_entry_date = self.Time.date()
        self.Debug(
            "Unexpected exercise or assignment handling: {}".format(
                assignment_event
            )
        )

    def _is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdateSubmitted
        )

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate
