        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-500, 500)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_count = 0
        self._bucket_closes = []

        self.held_symbol = None
        self.entry_price = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._process_time_stop(current_date)

        if self.held_symbol is not None and self.entry_price is not None:
            self._process_profit_target(slice)

        bars = slice.Bars
        if self.spy not in bars:
            return

        self._process_minute_bar(bars[self.spy], slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        minute = bar.Time.replace(second=0, microsecond=0)
        local_time = minute.time()

        if local_time < datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time >= datetime.strptime("16:00", "%H:%M").time():
            return

        bucket_minute = ((minute.hour * 60 + minute.minute - 570) // 5) * 5 + 570
        bucket_start = minute.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60
        )

        if self._bucket_start is None or bucket_start.date() != self._bucket_start.date():
            self._bucket_start = bucket_start
            self._bucket_count = 0
            self._bucket_closes = []

        elif bucket_start != self._bucket_start:
            self._finish_bucket(slice)

            self._bucket_start = bucket_start
            self._bucket_count = 0
            self._bucket_closes = []

        expected_time = self._bucket_start + timedelta(minutes=self._bucket_count)

        if minute != expected_time:
            self._bucket_count = 0
            self._bucket_closes = []
            if minute != self._bucket_start:
                return

        self._bucket_closes.append(float(bar.Close))
        self._bucket_count += 1

    def _finish_bucket(self, slice: Slice):
        if self._bucket_start is None:
            return

        if self._bucket_count != 5:
            return

        close = self._bucket_closes[-1]
        end_time = self._bucket_start + timedelta(minutes=5)

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = float(self.fast.Current.Value) if previous_ready else None
        previous_slow = float(self.slow.Current.Value) if previous_ready else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        end_clock = end_time.time()
        eligible_start = datetime.strptime("09:45", "%H:%M").time()
        eligible_end = datetime.strptime("14:30", "%H:%M").time()

        bullish_cross = (
            previous_fast <= previous_slow and
            float(self.fast.Current.Value) > float(self.slow.Current.Value)
        )

        if eligible_start <= end_clock <= eligible_end and bullish_cross:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.no_entry_date == current_date:
            return
        if self.held_symbol is not None:
            return
        if self._order_is_open(self.entry_ticket):
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped entry: current SPY price unavailable.")
            return

        spy_price = float(slice.Bars[self.spy].Close)
        if spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = slice.OptionChains
        chain = None

        for candidate in chains.Values:
            if candidate.Symbol == self.option_symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        minimum_expiry = current_date + timedelta(days=7)
        expirations = sorted({
            self._contract_expiry_date(contract)
            for contract in chain
            if self._contract_expiry_date(contract) >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if self._contract_expiry_date(contract) == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.held_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry {selected_expiry}, strike {selected.Strike}"
        )

    def _process_profit_target(self, slice: Slice):
        if self.held_symbol not in slice.QuoteBars:
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (float(bid) + float(ask)) / 2.0

        if midpoint >= 1.50 * float(self.entry_price):
            self._submit_exit("50% profit target reached")

    def _process_time_stop(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self._contract_expiry_date_from_symbol(self.held_symbol)
        stop_date = self._previous_trading_day(expiry_date)

        if (
            current_date == stop_date and
            self.Time.time() >= datetime.strptime("15:45", "%H:%M").time()
        ):
            self._submit_exit("pre-expiration time stop")

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self._contract_expiry_date_from_symbol(self.held_symbol)

        if current_date >= expiry_date:
            self.no_entry_date = current_date
            self._submit_exit("expiration processing liquidation")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return
        if self._order_is_open(self.exit_ticket):
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(f"Unexpected assignment or exercise: {order_event}")

        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entry filled: {self.held_symbol}, "
                    f"price {self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order canceled or invalid.")
                if self.Portfolio[self.held_symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_symbol}")
                if self.Portfolio[self.held_symbol].Quantity == 0:
                    self.held_symbol = None
                    self.entry_price = None
                    self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def _order_is_open(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _contract_expiry_date(self, contract):
        return contract.Expiry.date()

    def _contract_expiry_date_from_symbol(self, symbol):
        return symbol.ID.Date.date()

    def _previous_trading_day(self, date_value):
        candidate = datetime.combine(
            date_value - timedelta(days=1),
            datetime.min.time()
        )

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

