        self._process_time_stop(slice, current_date)
        self._process_profit_target(slice)

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.Time
        bar_date = bar_time.date()

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            return

        session_start = datetime.combine(bar_date, time(9, 30))
        bucket_number = int((bar_time - session_start).total_seconds() // 300)
        bucket_start = session_start + timedelta(minutes=5 * bucket_number)

        if self._bucket_start is not None and bucket_start != self._bucket_start:
            self._finalize_five_minute_bar(slice)

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._minute_bars = {}

        self._minute_bars[bar_time] = minute_bar

    def _finalize_five_minute_bar(self, slice: Slice):
        if self._bucket_start is None:
            return

        expected_times = [
            self._bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._minute_bars for t in expected_times):
            self._bucket_start = None
            self._minute_bars = {}
            return

        bars = [self._minute_bars[t] for t in expected_times]

        consolidated = TradeBar(
            self._bucket_start,
            self.spy.Symbol,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._update_averages_and_check_signal(consolidated, slice)

        self._bucket_start = None
        self._minute_bars = {}

