        previous_fast = None
        previous_slow = None

        if len(self.fast_window) >= 5:
            previous_fast = sum(list(self.fast_window)[-5:]) / 5.0

        if len(self.slow_window) >= 20:
            previous_slow = sum(list(self.slow_window)[-20:]) / 20.0

        self.fast_window.append(bar.Close)
        self.slow_window.append(bar.Close)

        if len(self.fast_window) < 5 or len(self.slow_window) < 20:
            return

        current_fast = sum(self.fast_window) / 5.0
        current_slow = sum(self.slow_window) / 20.0

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self._no_entry_date == current_date:
            return

        if self._entry_order_is_open():
            return

        if self._option_symbol is not None:
            if self.Portfolio[self._option_symbol].Invested:
                return

        spy_bar = slice.Bars.get(self.spy.Symbol)
        if spy_bar is None or spy_bar.Close <= 0:
            self.Debug("Skipped call selection: SPY price unavailable.")
            return

        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            self.Debug("Skipped call selection: option chain unavailable.")
            return

        contracts = list(chain.Contracts.Values)
        if not contracts:
            self.Debug("Skipped call selection: option chain is empty.")
            return

        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not eligible_expirations:
            self.Debug("Skipped call selection: no expiration at least 7 days away.")
            return

        selected_expiry = eligible_expirations[0]
        minimum_strike = 1.01 * spy_bar.Close

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self._option_symbol = selected.Symbol
        self._entry_price = None
        self._expiration_stop_date = self._previous_trading_day(selected.Expiry.date())

        ticket = self.MarketOrder(selected.Symbol, 1, tag="Bullish five-minute crossover")
        self._entry_order_id = ticket.OrderId

    def _process_profit_target(self, slice: Slice):
        if self._option_symbol is None or self._entry_price is None:
            return

        holding = self.Portfolio[self._option_symbol]
        if not holding.Invested or self._exit_order_is_open():
            return

        contract = self._get_current_contract(slice, self._option_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._cancel_exit_order()
            ticket = self.MarketOrder(
                self._option_symbol,
                -holding.Quantity,
                tag="50 percent profit target"
            )
            self._exit_order_id = ticket.OrderId
            self.Debug(
                f"Exit submitted: profit target for {self._option_symbol.Value}"
            )

    def _process_time_stop(self, slice: Slice, current_date):
        if self._option_symbol is None or self._expiration_stop_date is None:
            return

        holding = self.Portfolio[self._option_symbol]
        if not holding.Invested or self._exit_order_is_open():
            return

        if (
            current_date == self._expiration_stop_date
            and self.Time.time() >= time(15, 45)
        ):
            self._cancel_exit_order()
            ticket = self.MarketOrder(
                self._option_symbol,
                -holding.Quantity,
                tag="Expiration-eve time stop"
            )
            self._exit_order_id = ticket.OrderId
            self.Debug(
                f"Exit submitted: expiration-eve time stop for "
                f"{self._option_symbol.Value}"
            )

    def _process_expiration(self, sliced: Slice, current_date):
        if self._option_symbol is None:
            return

        holding = self.Portfolio[self._option_symbol]

        if (
            current_date >= self._option_symbol.ID.Date.date()
            and self._expiration_processed_date != current_date
        ):
            self._expiration_processed_date = current_date
            self._no_entry_date = current_date

            if holding.Invested and not self._exit_order_is_open():
                self._cancel_exit_order()
                ticket = self.MarketOrder(
                    self._option_symbol,
                    -holding.Quantity,
                    tag="Expiration protection liquidation"
                )
                self._exit_order_id = ticket.OrderId
                self.Debug(
                    f"Exit submitted: expiration protection for "
                    f"{self._option_symbol.Value}"
                )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.OrderId == self._entry_order_id:
            if order_event.FillQuantity > 0 and self._entry_price is None:
                self._entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self._option_symbol.Value} at "
                    f"{self._entry_price:.4f}"
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry skipped: entry order did not fill.")
                self._entry_order_id = None

        if order_event.OrderId == self._exit_order_id:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    f"Exit filled: {order_event.Symbol.Value} at "
                    f"{order_event.FillPrice:.4f}"
                )
                self._exit_order_id = None
                self._entry_price = None
                self._expiration_stop_date = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self._exit_order_id = None

        try:
            order = self.Transactions.GetOrderById(order_event.OrderId)
            if order.Type == OrderType.OptionExercise:
                self.Debug(
                    f"Unexpected option exercise or assignment handling: "
                    f"{order_event.Symbol.Value}"
                )
        except Exception:
            pass

    def OnAssignmentOrder(self, assignment_event: OrderEvent):
        self.Debug(
            f"Unexpected option assignment handling: "
            f"{assignment_event.Symbol.Value}"
        )

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        chain = slice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return None
        return chain.Contracts.get(symbol)

    def _entry_order_is_open(self):
        if self._entry_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self._entry_order_id)
        return order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _exit_order_is_open(self):
        if self._exit_order_id is None:
            return False

        order = self.Transactions.GetOrderById(self._exit_order_id)
        return order.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _cancel_exit_order(self):
        if self._exit_order_id is not None and self._exit_order_is_open():
            self.Transactions.CancelOrder(self._exit_order_id)

    def _previous_trading_day(self, expiration_date):
        exchange_hours = self.Securities[self.spy.Symbol].Exchange.Hours
        candidate = expiration_date - timedelta(days=1)

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

