        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )
        self.spy_option = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._pending_signal = False
        self._pending_signal_time = None
        self._pending_signal_price = None

        self._entry_ticket = None
        self._held_option = None
        self._entry_price = None
        self._exit_ticket = None
        self._time_stop_date = None
        self._expiration_processing_date = None

        consolidator = TradeBarConsolidator(timedelta(minutes=5))
        consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, consolidator)

    def OnFiveMinuteBar(self, sender, bar):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if (
            previous_fast is None
            or previous_slow is None
            or not self.fast.IsReady
            or not self.slow.IsReady
        ):
            return

        bar_time = bar.EndTime.time()
        if not (time(9, 45) <= bar_time <= time(14, 30)):
            return

        if self.fast.Current.Value > self.slow.Current.Value:
            if previous_fast <= previous_slow:
                self._pending_signal = True
                self._pending_signal_time = bar.EndTime
                self._pending_signal_price = bar.Close

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self.ProcessExpiration(current_date)

        if self._pending_signal:
            if (
                self._pending_signal_time is not None
                and self.Time >= self._pending_signal_time
            ):
                self._pending_signal = False
                self.TryEnter(slice)

        self.ProcessExits(slice)

    def TryEnter(self, slice: Slice):
        if self._held_option is not None:
            return

        if self._entry_ticket is not None and self.IsOrderOpen(self._entry_ticket):
            return

        if (
            self._expiration_processing_date is not None
            and self._expiration_processing_date == self.Time.date()
        ):
            return

        spy_price = self._pending_signal_price
        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped selection: invalid SPY price.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        contracts = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                expiry_date = contract.Expiry.date()

                if (
                    expiry_date >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped selection: no eligible option chain or expiration.")
            return

        nearest_expiry = min(contract.Expiry.date() for contract in contracts)
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == nearest_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no eligible call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self._time_stop_date = self.PreviousTradingDate(nearest_expiry)

        self.Debug(
            f"Entry submitted: {selected.Symbol}, "
            f"expiry={nearest_expiry}, strike={selected.Strike}"
        )

    def ProcessExits(self, slice: Slice):
        if self._held_option is None:
            return

        holding = self.Portfolio[self._held_option]
        if not holding.Invested:
            return

        current_date = self.Time.date()

        if (
            self._time_stop_date == current_date
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("time stop")
            return

        quote = self.GetCurrentQuote(slice, self._held_option)
        if quote is None or self._entry_price is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self._entry_price:
            self.SubmitExit("50% profit target")

    def ProcessExpiration(self, current_date):
        if self._held_option is None:
            return

        expiry_date = self._held_option.ID.Date.date()

        if current_date != expiry_date:
            return

        if self._expiration_processing_date == current_date:
            return

        self._expiration_processing_date = current_date

        if self._entry_ticket is not None and self.IsOrderOpen(self._entry_ticket):
            self._entry_ticket.Cancel("expiration processing")

        if self.Portfolio[self._held_option].Invested:
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self._held_option is None:
            return

        holding = self.Portfolio[self._held_option]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self._exit_ticket is not None and self.IsOrderOpen(self._exit_ticket):
            self._exit_ticket.Cancel(f"replaced by {reason}")

        self._exit_ticket = self.MarketOrder(
            self._held_option,
