                    ask = contract.AskPrice

                    if bid is not None and ask is not None and bid > 0 and ask > 0:
                        return bid, ask

        if slice.BidAskBars.ContainsKey(symbol):
            quote = slice.BidAskBars[symbol]
            if quote.Bid is not None and quote.Ask is not None:
                if quote.Bid > 0 and quote.Ask > 0:
                    return quote.Bid, quote.Ask

        return None

    def PreviousTradingDate(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(
            datetime.combine(candidate, time.min)
        ):
            candidate -= timedelta(days=1)

