    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        status = ticket.Status
        return status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
        )

    def OnOrderEvent(self, order_event):
        if self._entry_ticket is not None:
            if order_event.OrderId == self._entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self._held_option = order_event.Symbol
                    self._entry_price = order_event.FillPrice
                    self._entry_ticket = None

                    self.Debug(
                        f"Entry filled: {self._held_option}, "
                        f"price={self._entry_price}"
                    )

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self.Debug(
                        f"Entry order failed: {order_event.Status}"
                    )
                    self._entry_ticket = None

        if self._exit_ticket is not None:
            if order_event.OrderId == self._exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        f"Exit filled: {order_event.Symbol}, "
                        f"price={order_event.FillPrice}"
                    )
                    self._exit_ticket = None
                    self._held_option = None
                    self._entry_price = None
                    self._time_stop_date = None

                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                    OrderStatus.Rejected,
                ):
                    self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(f"Unexpected option exercise or assignment: {assignment_event}")

