        today = self.Time.date()

        if self.expiration_processed_date != today:
            self.expiration_processed_date = today
            self.no_entry_date = None
            self._process_expiration_start(today)

        if self.held_symbol is not None:
            self._process_time_stop(today)
            self._process_profit_target(slice)

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time

        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return
        if bar_time.hour >= 16:
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start != bucket_start:
            self._finalize_bucket(slice)
            self.current_bucket_start = bucket_start
            self.current_bucket_bars = []

        if self.current_bucket_bars:
            expected_time = self.current_bucket_bars[-1].Time + timedelta(minutes=1)
            if bar_time != expected_time:
                self.current_bucket_bars = []

        self.current_bucket_bars.append(bar)

        if len(self.current_bucket_bars) == 5:
            self._finalize_bucket(slice)
            self.current_bucket_bars = []

    def _finalize_bucket(self, slice: Slice):
        if self.current_bucket_start is None:
            return

        bars = self.current_bucket_bars
        if len(bars) != 5:
            return

        for first, second in zip(bars, bars[1:]):
            if second.Time != first.Time + timedelta(minutes=1):
                return

        close = bars[-1].Close

        prior_fast = None
        prior_slow = None
        if len(self.closes) >= self.fast_period:
            prior_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        if len(self.closes) >= self.slow_period:
            prior_slow = sum(self.closes) / self.slow_period

        self.closes.append(float(close))

        if len(self.closes) >= self.fast_period:
            current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
        else:
            current_fast = None

        if len(self.closes) >= self.slow_period:
            current_slow = sum(self.closes) / self.slow_period
        else:
            current_slow = None

        bar_end = self.current_bucket_start + timedelta(minutes=5)
        eligible_time = time(9, 45) <= bar_end.time() <= time(14, 30)

        bullish_cross = (
            prior_fast is not None and
            prior_slow is not None and
            current_fast is not None and
            current_slow is not None and
            prior_fast <= prior_slow and
            current_fast > current_slow
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, float(close))

        if current_fast is not None and current_slow is not None:
            self.previous_fast = current_fast
            self.previous_slow = current_slow

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_date == self.Time.date():
            return
        if self.held_symbol is not None:
            return
        if self._entry_order_open():
            return
        if self._has_option_holding():
            return

        chain = None
        for candidate in slice.OptionChains.Values:
            if candidate.Symbol == self.spy_option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain.Contracts.Values
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain.Contracts.Values
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: " + str(selected.Symbol))

    def _process_profit_target(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return
        if self._exit_order_open():
            return
        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = slice.QuoteBars[self.held_symbol]
        if quote.Bid is None or quote.Ask is None:
            return

        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _process_time_stop(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if not self._is_immediately_preceding_trading_day(today, expiry):
            return

        if self.Time.hour == 15 and self.Time.minute == 45:
            self._submit_exit("expiration-eve time stop")

    def _process_expiration_start(self, today):
        if self.held_symbol is None:
            return

        expiry = self.held_symbol.ID.Date.date()
        if today >= expiry:
            self.no_entry_date = today
            self._submit_exit("unexpected expiration-day holding")
            self.Debug("Unexpected option holding at expiration processing.")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return
        if self._exit_order_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order.")

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug("Exit submitted: " + reason)

    def _is_immediately_preceding_trading_day(self, today, expiry):
        candidate = expiry - timedelta(days=1)

        while candidate >= today - timedelta(days=10):
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
                return today == candidate
            candidate -= timedelta(days=1)

        return False

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False

        return self.exit_ticket.Status in [
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        ]

    def _has_option_holding(self):
        for security in self.Portfolio.Values:
            if security.Type == SecurityType.Option and security.Invested:
                return True
        return False

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status in [OrderStatus.Filled, OrderStatus.PartiallyFilled]:
                if order_event.FillQuantity > 0:
                    self.held_symbol = order_event.Symbol
                    self.entry_price = float(order_event.FillPrice)

                    if order_event.Status == OrderStatus.Filled:
                        self.Debug(
                            "Entry filled: {} at {:.4f}".format(
                                self.held_symbol,
                                self.entry_price
                            )
                        )
                        self.entry_ticket = None

            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_
            ]:
                if self.held_symbol is None:
                    self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(order_event.Symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in [
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ]:
                self.exit_ticket = None

        try:
            if order_event.IsAssignment:
                self.Debug(
                    "Unexpected exercise or assignment: " +
                    str(order_event.Symbol)
                )
        except Exception:
            pass

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected exercise or assignment: " +
            str(assignment_event.Symbol)
        )

