from collections import deque
from datetime import datetime, timedelta


class SpyLongCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = deque(maxlen=self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_start = None
        self.bucket_bars = {}

        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.expiration_processing_date = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        self._process_expiration(slice)
        self._process_exit_checks(slice)

        bar = self._get_spy_bar(slice)
        if bar is not None:
            self._process_minute_bar(bar, slice)

    def _get_spy_bar(self, slice: Slice):
        try:
            return slice.Bars.get(self.spy.Symbol)
        except Exception:
            try:
                return slice.Bars[self.spy.Symbol]
            except Exception:
                return None

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        local_time = bar.Time
        if hasattr(local_time, "replace"):
            local_time = local_time.replace(tzinfo=None)

        current_date = local_time.date()
        current_minutes = local_time.hour * 60 + local_time.minute
        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if (
            local_time.weekday() >= 5
            or current_minutes < session_start
            or current_minutes >= session_end
        ):
            return

        bucket_offset = (current_minutes - session_start) // 5
        bucket_start_minutes = session_start + bucket_offset * 5
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_start_minutes // 60,
            bucket_start_minutes % 60,
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._emit_bucket_if_complete(slice)

        if self.bucket_start != bucket_start:
            self.bucket_date = current_date
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        minute_key = (local_time.hour, local_time.minute)
        self.bucket_bars[minute_key] = bar

        if len(self.bucket_bars) == 5:
            self._emit_bucket_if_complete(slice)

    def _emit_bucket_if_complete(self, slice: Slice):
        if self.bucket_start is None:
            return

        expected = set()
        for offset in range(5):
            minute = self.bucket_start + timedelta(minutes=offset)
            expected.add((minute.hour, minute.minute))

        if set(self.bucket_bars.keys()) != expected:
            return

        bars = [
            self.bucket_bars[(self.bucket_start + timedelta(minutes=i)).hour,
                             (self.bucket_start + timedelta(minutes=i)).minute]
            for i in range(5)
        ]

        consolidated_close = bars[-1].Close
        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(float(consolidated_close))

        if len(self.closes) >= self.slow_period:
            current_fast = sum(list(self.closes)[-self.fast_period:]) / self.fast_period
            current_slow = sum(self.closes) / self.slow_period

            crossover = (
                prior_fast is not None
                and prior_slow is not None
                and prior_fast <= prior_slow
                and current_fast > current_slow
            )

            self.previous_fast = current_fast
            self.previous_slow = current_slow

            bar_end = self.bucket_start + timedelta(minutes=5)
            end_minutes = bar_end.hour * 60 + bar_end.minute

            if (
                crossover
                and 9 * 60 + 45 <= end_minutes <= 14 * 60 + 30
            ):
                self._try_enter(slice, float(consolidated_close), bar_end.date())

    def _try_enter(self, slice: Slice, spy_price: float, signal_date):
        if self.no_entry_date == signal_date:
            return

        if self.held_symbol is not None or self._entry_is_open():
            return

        if self._has_any_option_holding():
            return

        chain = self._get_option_chain(slice)
        if chain is None:
            self.Debug("Skipped call entry: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = list(chain)
        eligible_expiries = sorted(
            {
                contract.Expiry.date()
                for contract in contracts
                if contract.Right == OptionRight.Call
                and contract.Expiry.date() >= minimum_expiry
            }
        )

        if not eligible_expiries:
            self.Debug("Skipped call entry: no expiration at least 7 calendar days out.")
            return

        selected_expiry = eligible_expiries[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute SMA crossover entry"
        )

        self.held_symbol = selected.Symbol
        self.entry_price = None
        self.expiration_date = selected_expiry
        self.expiration_processing_date = selected_expiry
        self.time_stop_date = self._immediately_preceding_trading_day(
            selected_expiry
        )

