        if quantity == 0:
            return

        if self.exit_ticket is not None:
            try:
                self.exit_ticket.Cancel("Replacing open exit order")
            except Exception:
                pass

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            quantity,
            tag=reason
        )
        self.Debug("Submitted SPY call exit: {}".format(reason))

    def _get_option_chain(self, slice: Slice):
