        session_start = 9 * 60 + 30
        session_end = 16 * 60

        if (
            local_time.weekday() >= 5
            or current_minutes < session_start
            or current_minutes >= session_end
        ):
            return

        bucket_offset = (current_minutes - session_start) // 5
        bucket_start_minutes = session_start + bucket_offset * 5
        bucket_start = datetime(
            current_date.year,
            current_date.month,
            current_date.day,
            bucket_start_minutes // 60,
            bucket_start_minutes % 60,
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
