                self._complete_bucket()
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _complete_bucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(t in self.bucket_bars for t in expected_times):
            close = self.bucket_bars[expected_times[-1]].Close
            end_time = self.bucket_start + timedelta(minutes=5)
            self._on_five_minute_bar(end_time, close)

        self.bucket_start = None
        self.bucket_bars = {}

    def _on_five_minute_bar(self, end_time, close):
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and eligible_start <= end_time.time() <= eligible_end
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._entry_signal_pending = True

    def _try_entry(self, slice):
        if not getattr(self, "_entry_signal_pending", False):
            return

        self._entry_signal_pending = False

        chains = slice.OptionChains
        if chains is None or self.option_symbol not in chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        chain = chains[self.option_symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no expiration satisfies 7-day rule.")
            return

        selected_expiry = expiries[0]
