            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_expiry = selected.Expiry
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

    def _process_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target reached")

    def _process_time_stop(self, today):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if (
            today == self._preceding_trading_day(expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-eve time stop")

    def _process_expiration(self, today):
        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry_date:
                self.blocked_entry_date = today
                self._submit_exit("Unexpected position at expiration")
                return

        if self.entry_ticket is not None and self._entry_order_open():
            if self.entry_expiry is not None and today >= self.entry_expiry.date():
                self.entry_ticket.Cancel("Expiration processing")
                self.blocked_entry_date = today
                self.Debug("Canceled entry order during expiration processing.")

    def _submit_exit(self, reason):
        if self.held_symbol is None or self._exit_order_open():
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

        self.Transactions.CancelOpenOrders(self.held_symbol)
        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _preceding_trading_day(self, expiry_date):
        exchange_hours = self.Securities[self.spy].Exchange.Hours
        candidate = expiry_date - timedelta(days=1)

        while candidate >= self.StartDate.date():
            if exchange_hours.IsDateOpen(candidate):
                return candidate
            candidate -= timedelta(days=1)

        return None

    def _is_regular_session_time(self, value):
        return (
            value.weekday() < 5
            and time(9, 30) <= value.time() < time(16, 0)
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status not in (
            OrderStatus.Filled,
