        self.entry_expiry = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.blocked_entry_date = None

    def OnData(self, slice):
        today = self.Time.date()

        self._process_expiration(today)
        self._process_time_stop(today)
        self._process_profit_target(slice)

        bar = slice.Bars.get(self.spy)
        if bar is not None:
            self._process_minute_bar(bar)

        if (
            self.held_symbol is None
            and not self._entry_order_open()
            and self.blocked_entry_date != today
        ):
            self._try_entry(slice)

    def _process_minute_bar(self, bar):
        bar_time = bar.Time

        if not self._is_regular_session_time(bar_time):
            if self.bucket_start is not None:
                self._complete_bucket()
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._complete_bucket()

        if self.bucket_start != bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        self.bucket_bars[bar_time] = bar

    def _complete_bucket(self):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if all(t in self.bucket_bars for t in expected_times):
            close = self.bucket_bars[expected_times[-1]].Close
            end_time = self.bucket_start + timedelta(minutes=5)
            self._on_five_minute_bar(end_time, close)

        self.bucket_start = None
        self.bucket_bars = {}

    def _on_five_minute_bar(self, end_time, close):
        self.closes.append(float(close))

        if len(self.closes) > self.slow_period + 1:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period + 1:
            return

        previous = self.closes[:-1]
        current = self.closes

        previous_fast = sum(previous[-self.fast_period:]) / self.fast_period
        previous_slow = sum(previous[-self.slow_period:]) / self.slow_period
        current_fast = sum(current[-self.fast_period:]) / self.fast_period
        current_slow = sum(current[-self.slow_period:]) / self.slow_period

        eligible_start = time(9, 45)
        eligible_end = time(14, 30)

        bullish_cross = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_cross
            and eligible_start <= end_time.time() <= eligible_end
            and self.held_symbol is None
            and not self._entry_order_open()
        ):
            self._entry_signal_pending = True

    def _try_entry(self, slice):
        if not getattr(self, "_entry_signal_pending", False):
            return

        self._entry_signal_pending = False

        chains = slice.OptionChains
        if chains is None or self.option_symbol not in chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        chain = chains[self.option_symbol]
        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped call selection: no expiration satisfies 7-day rule.")
            return

        selected_expiry = expiries[0]
        spy_price = float(self.Securities[self.spy].Price)

        if spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Right == OptionRight.Call
                and contract.Strike >= minimum_strike
            )
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_expiry = selected.Expiry
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover call entry"
        )

    def _process_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self._exit_order_open():
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        contract = next(
            (
                item for item in chain
                if item.Symbol == self.held_symbol
            ),
            None
        )

        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target reached")

    def _process_time_stop(self, today):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if (
            today == self._preceding_trading_day(expiry_date)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("Expiration-eve time stop")

    def _process_expiration(self, today):
        if self.held_symbol is not None:
            expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

            if today >= expiry_date:
                self.blocked_entry_date = today
                self._submit_exit("Unexpected position at expiration")
                return

