        previous = expiry_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(previous.year, previous.month, previous.day)
        ):
            previous -= timedelta(days=1)

        return (
            current_date == previous
            and self.Time.time() >= time(15, 45)
        )

    def _cancel_entry_order(self):
        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration day")
        self.entry_order_open = False

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            order_event.Symbol.SecurityType == SecurityType.Option
            and (
                getattr(order_event, "IsAssignment", False)
                or order_event.OrderType == OrderType.OptionExercise
            )
        ):
            self.Debug("Unexpected option exercise or assignment: " + str(order_event))

        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_order_open = False
                self.held_contract = order_event.Symbol
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: " +
                    str(self.held_contract) +
                    " at " +
                    str(self.entry_price)
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.entry_order_open = False
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option exit filled: " + str(order_event.Symbol))
                self.exit_ticket = None
                self.held_contract = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.exit_ticket = None

