        minute_of_day = local_time.hour * 60 + local_time.minute
        market_open = 9 * 60 + 30

        bucket_end = market_open + ((minute_of_day - market_open + 4) // 5) * 5
        bucket_start = bucket_end - 5

        bucket_key = (local_time.date(), bucket_end)

        if self.bucket_date is None:
            self.bucket_date = local_time.date()
            self.bucket_end_minute = bucket_end
        elif bucket_key != (self.bucket_date, self.bucket_end_minute):
            signal = self._finalize_bucket()
            self.bucket_date = local_time.date()
            self.bucket_end_minute = bucket_end
            self.bucket_bars = {
