                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = order_event.Symbol.ID.Date.date()
                self.Debug(
                    "Entry filled: {} at {:.4f}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if order_event.Status in (
            OrderStatus.Assigned,
            OrderStatus.Exercised
        ):
            self.Debug(
                "Unexpected exercise or assignment: {} {}".format(
                    order_event.Symbol,
                    order_event.Status
                )
            )

    def _previous_trading_day(self, expiration_date):
        date = expiration_date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(date.year, date.month, date.day)
        ):
            date -= timedelta(days=1)
        return date

    def _is_order_done(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )
