from AlgorithmImports import *
from datetime import timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        self.spy = self.AddEquity("SPY", Resolution.Minute, extendedMarketHours=False)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_closes = {}
        self._bucket_finalized = False

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._blocked_entry_date = None

    def OnData(self, slice: Slice):
        self._manage_open_position(slice)

        spy_bar = None
        try:
            spy_bar = slice.Bars[self.spy_symbol]
        except Exception:
            spy_bar = None

        if spy_bar is not None:
            self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        bar_time = bar.Time
        local_time = bar_time.time()

        if local_time < time(9, 30) or local_time >= time(16, 0):
            return

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_minute = 9 * 60 + 30 + (minutes_from_open // 5) * 5
        bucket_start = bar_time.replace(
            hour=bucket_minute // 60,
            minute=bucket_minute % 60,
            second=0,
            microsecond=0
        )

        if self._bucket_start != bucket_start:
            self._bucket_start = bucket_start
            self._bucket_closes = {}
            self._bucket_finalized = False

        if self._bucket_finalized:
            return

        self._bucket_closes[bar_time] = float(bar.Close)

        if len(self._bucket_closes) == 5:
            close = list(sorted(self._bucket_closes.items()))[-1][1]
            bar_end = bucket_start + timedelta(minutes=5)
            self._bucket_finalized = True
            self._process_five_minute_bar(bar_end, close, slice)

    def _process_five_minute_bar(self, bar_end, close, slice: Slice):
        was_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        if not was_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow and
            self.fast.Current.Value > self.slow.Current.Value
        )

        end_time = bar_end.time()
        eligible_time = time(9, 45) <= end_time <= time(14, 30)

        if bullish_cross and eligible_time:
            self._try_enter(slice, close, bar_end.date())

    def _try_enter(self, slice: Slice, spy_price: float, signal_date):
        if (
            self._held_symbol is not None or
            self._entry_ticket is not None or
            self._exit_ticket is not None or
            self._blocked_entry_date == signal_date
        ):
            return

        try:
            chain = slice.OptionChains[self.option_symbol]
            contracts = list(chain.Contracts.Values)
        except Exception:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = signal_date + timedelta(days=7)
        eligible = []

        for contract in contracts:
            try:
                expiry_date = self._symbol_expiry_date(contract.Symbol)
                if expiry_date >= minimum_expiry:
                    eligible.append(contract)
            except Exception:
                continue

        if not eligible:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        nearest_expiry = min(
            self._symbol_expiry_date(contract.Symbol) for contract in eligible
        )

        minimum_strike = 1.01 * spy_price
        candidates = [
            contract for contract in eligible
            if self._symbol_expiry_date(contract.Symbol) == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self._entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            "Bullish five-minute SPY crossover"
        )

    def _manage_open_position(self, slice: Slice):
        if self._held_symbol is None:
            return

        current_date = self.Time.date()
        expiry_date = self._symbol_expiry_date(self._held_symbol)

        if current_date >= expiry_date:
            self._blocked_entry_date = current_date
            self._submit_exit("Expiration protection")
            return

        if (
            self.Time.time() >= time(15, 45) and
            current_date == self._previous_trading_day(expiry_date)
        ):
            self._submit_exit("Expiration-eve time stop")
            return

        if self._exit_ticket is not None:
            return

        try:
            quote_bar = slice.QuoteBars[self._held_symbol]
            bid = quote_bar.Bid.Close if quote_bar.Bid is not None else None
            ask = quote_bar.Ask.Close if quote_bar.Ask is not None else None
        except Exception:
            return

        if (
            bid is None or ask is None or
            bid <= 0 or ask <= 0 or
            self._entry_price is None
        ):
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self._entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self._held_symbol is None or self._exit_ticket is not None:
            return

        quantity = self.Portfolio[self._held_symbol].Quantity
        if quantity <= 0:
            return

        for order in self.Transactions.GetOpenOrders(self._held_symbol):
            if self._entry_ticket is None or order.Id != self._entry_ticket.OrderId:
                self.Transactions.CancelOrder(order.Id)

        self._exit_ticket = self.MarketOrder(
            self._held_symbol,
            -quantity,
            reason
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self._entry_ticket is not None and
                order_event.OrderId == self._entry_ticket.OrderId
            ):
                self._held_symbol = order_event.Symbol
                self._entry_price = order_event.FillPrice
                self._entry_ticket = None
                self.Debug(
                    "Entered 1 SPY call: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )

            elif (
                self._exit_ticket is not None and
                order_event.OrderId == self._exit_ticket.OrderId
            ):
                self.Debug(
                    "Exited SPY call: {} at {:.4f}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self._exit_ticket = None
                self._held_symbol = None
                self._entry_price = None

        elif order_event.Status in (
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Margin 부족 if False else OrderStatus.Invalid
        ):
            if (
                self._entry_ticket is not None and
                order_event.OrderId == self._entry_ticket.OrderId
            ):
                self.Debug("Entry order was not filled.")
                self._entry_ticket = None

            if (
                self._exit_ticket is not None and
                order_event.OrderId == self._exit_ticket.OrderId
            ):
                self._exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option assignment detected.")

    def OnExerciseOrder(self, exercise_event):
