            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw,
            extendedMarketHours=False
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )

        self.closes = deque(maxlen=20)
        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_submitted = False

        self.current_date = None
        self.no_entry_today = False

    def OnData(self, data: Slice):
        algorithm_date = self.Time.date()

        if self.current_date != algorithm_date:
            self.current_date = algorithm_date
            self.no_entry_today = False

        if self.held_symbol is not None:
            expiry = self.held_symbol.ID.Date.date()

            if algorithm_date >= expiry:
                self.no_entry_today = True
                self._submit_exit("expiration processing")

            elif (
                algorithm_date == self._previous_trading_day(expiry)
                and self.Time.hour == 15
                and self.Time.minute >= 45
            ):
                self._submit_exit("expiration time stop")

            elif not self.exit_submitted and self.entry_price is not None:
                quote = self._option_quote(data, self.held_symbol)

                if quote is not None:
                    bid, ask = quote
                    midpoint = (bid + ask) / 2.0

                    if midpoint >= 1.5 * self.entry_price:
                        self._cancel_open_exit()
                        self._submit_exit("50% profit target")

        crossover_bar = self._update_five_minute_bar(data)

        if crossover_bar and not self.no_entry_today:
            self._evaluate_entry(data)

    def _update_five_minute_bar(self, data: Slice):
        if self.spy not in data.Bars:
            return False

        minute_bar = data.Bars[self.spy]
        minute_start = minute_bar.Time.replace(second=0, microsecond=0)

        bucket_start = minute_start.replace(
            minute=minute_start.minute - (minute_start.minute % 5)
        )

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bucket_start < self.bucket_start:
            return False

        if bucket_start != self.bucket_start:
            crossover = self._process_bucket(self.bucket_start, self.bucket_bars)
            self.bucket_start = bucket_start
            self.bucket_bars = {}
        else:
            crossover = False

        self.bucket_bars[minute_start] = minute_bar
        return crossover

    def _process_bucket(self, bucket_start, bars):
        expected_times = {
            bucket_start + timedelta(minutes=i) for i in range(5)
        }

        if set(bars.keys()) != expected_times:
            return False

        ordered = [bars[bucket_start + timedelta(minutes=i)] for i in range(5)]

        five_minute_bar = TradeBar(
            bucket_start,
            self.spy,
            ordered[0].Open,
            max(bar.High for bar in ordered),
            min(bar.Low for bar in ordered),
            ordered[-1].Close,
            sum(bar.Volume for bar in ordered),
            timedelta(minutes=5)
        )

        return self._process_completed_bar(five_minute_bar)

    def _process_completed_bar(self, bar):
        if len(self.closes) == 20:
            previous_fast = sum(list(self.closes)[-5:]) / 5.0
            previous_slow = sum(self.closes) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(bar.Close))

        if len(self.closes) < 20:
            return False

        current_fast = sum(list(self.closes)[-5:]) / 5.0
        current_slow = sum(self.closes) / 20.0

        bullish_cross = (
            previous_fast is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar.EndTime
        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        return bullish_cross and eligible_time

    def _evaluate_entry(self, data: Slice):
        if self.held_symbol is not None or self._entry_is_open():
            return

        if self.spy not in data.Bars:
            return

        spy_price = float(data.Bars[self.spy].Close)
        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)

        chains = list(data.OptionChains)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        candidates = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Right == OptionRight.Call
                    and contract.Expiry.date() >= minimum_expiry
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = min(
            contract.Expiry.date() for contract in candidates
        )

        strike_floor = 1.01 * spy_price
        strike_candidates = [
            contract for contract in candidates
            if (
                contract.Expiry.date() == selected_expiry
                and contract.Strike >= strike_floor
            )
        ]

        if not strike_candidates:
            self.Debug("Skipped call selection: no eligible strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish SPY call entry"
        )

    def _option_quote(self, data: Slice, symbol):
        for chain in data.OptionChains:
            for contract in chain:
                if contract.Symbol == symbol:
                    bid = float(contract.BidPrice)
                    ask = float(contract.AskPrice)

                    if bid > 0 and ask > 0:
                        return bid, ask

        return None

    def _submit_exit(self, reason):
        if self.held_symbol is None or self.exit_submitted:
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag="SPY call exit: " + reason
        )
        self.exit_submitted = True
        self.Debug("Submitted exit: " + reason)

    def _cancel_open_exit(self):
        if self.exit_ticket is None:
            return

        if self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        ):
            self.exit_ticket.Cancel("Replaced by profit-target exit")

    def _entry_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.exit_submitted = False
                self.Debug(
                    "Entered 1 SPY call at {:.4f}: {}".format(
                        self.entry_price,
                        str(self.held_symbol)
                    )
                )

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Exited SPY call at {:.4f}.".format(
                float(order_event.FillPrice)
            ))

            if self.held_symbol is None or not self.Portfolio[
                self.held_symbol
            ].Invested:
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.exit_submitted = False

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentEvent):
        self.Debug(
            "Unexpected option exercise or assignment: {}".format(
                str(assignment_event)
            )
        )

