from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 365)
        )

        self.fast = RollingWindow[float](5)
        self.slow = RollingWindow[float](20)

        self._bucket_date = None
        self._bucket_end = None
        self._bucket_closes = []
        self._last_consolidated_end = None

        self.entry_ticket = None
        self.entry_order_id = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.entry_blocked_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration_safety(current_date)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            self._process_spy_minute(spy_bar, slice)

        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_profit_target(slice)

    def _process_spy_minute(self, bar: TradeBar, slice: Slice):
        local_end = bar.EndTime
        if local_end.tzinfo is not None:
            local_end = local_end.replace(tzinfo=None)

        if local_end.weekday() >= 5:
            return

        current_time = local_end.time()
        if current_time < time(9, 31) or current_time > time(16, 0):
            return

        bucket_end_minute = ((local_end.hour * 60 + local_end.minute + 4) // 5) * 5
        bucket_end = datetime.combine(
            local_end.date(), time(bucket_end_minute // 60, bucket_end_minute % 60)
        )

        if self._bucket_end != bucket_end:
            if self._bucket_end is not None:
                self._finish_bucket(slice)

            self._bucket_date = local_end.date()
            self._bucket_end = bucket_end
            self._bucket_closes = []

        expected_start = self._bucket_end - timedelta(minutes=5)
        if local_end <= expected_start or local_end > self._bucket_end:
            return

        self._bucket_closes.append(float(bar.Close))

        if local_end == self._bucket_end:
            self._finish_bucket(slice)

    def _finish_bucket(self, slice: Slice):
        if self._bucket_end is None:
            return

        bucket_end = self._bucket_end
        closes = self._bucket_closes

        self._bucket_end = None
        self._bucket_date = None
        self._bucket_closes = []

        if bucket_end.time() < time(9, 35) or bucket_end.time() > time(16, 0):
            return

        # A complete five-minute bar requires all five minute bars.
        if len(closes) != 5:
            return

        close = closes[-1]
        self.fast.Add(close)
        self.slow.Add(close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        previous_fast = sum(self.fast[1:]) / 5.0
        previous_slow = sum(self.slow[1:]) / 20.0
        current_fast = sum(self.fast[i] for i in range(5)) / 5.0
        current_slow = sum(self.slow[i] for i in range(20)) / 20.0

        end_time = bucket_end.time()
        eligible = time(9, 45) <= end_time <= time(14, 30)
        bullish = previous_fast <= previous_slow and current_fast > current_slow

        if eligible and bullish:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        current_date = self.Time.date()

        if self.entry_blocked_date == current_date:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_finished(self.entry_ticket):
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiration = current_date + timedelta(days=7)
        candidates = []

        for chain in chains:
            for contract in chain:
                expiration = contract.Expiry.date()
                if (
                    contract.Right == OptionRight.Call
                    and expiration >= minimum_expiration
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no qualifying expiration/contracts.")
            return

        selected_expiration = min(contract.Expiry.date() for contract in candidates)
        minimum_strike = float(self.Securities[self.spy].Price) * 1.01

        strikes = [
            contract for contract in candidates
            if contract.Expiry.date() == selected_expiration
            and float(contract.Strike) >= minimum_strike
        ]

        if not strikes:
            self.Debug("Skipped call selection: no qualifying strike.")
            return

        selected = min(
            strikes,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.expiration_date = selected.Expiry.date()

    def _evaluate_profit_target(self, slice: Slice):
        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        contract = self._get_current_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _process_expiration_safety(self, current_date):
        if self.held_symbol is None or self.expiration_date is None:
            return

        if current_date >= self.expiration_date:
            self.entry_blocked_date = current_date
            self._submit_exit("expiration safety")

        elif (
            current_date == self.expiration_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_finished(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted: " + reason)

    def _get_current_contract(self, slice: Slice, symbol):
        if symbol is None:
            return None

        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def OnOrderEvent(self, order_event: OrderEvent):
        if order_event.Status == OrderStatus.Filled:
            if (
                self.entry_order_id is not None
                and order_event.OrderId == self.entry_order_id
            ):
                self.held_symbol = order_event.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: "
                    + str(self.held_symbol)
                    + " at "
                    + str(self.entry_price)
                )

            elif (
                self.exit_ticket is not None
                and order_event.OrderId == self.exit_ticket.OrderId
            ):
                self.Debug("Call exit filled: " + str(order_event.Symbol))
                self.held_symbol = None
                self.entry_price = None
                self.expiration_date = None
                self.exit_ticket = None

        message = str(order_event.Message).lower()
        if "assign" in message or "exercise" in message:
            self.Debug("Unexpected option exercise or assignment: " + str(order_event))

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option assignment handling: " + str(assignment_event))

    def _ticket_finished(self, ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.PartiallyFilled,
        )

