from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy_symbol = self.spy.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.option.Symbol
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(timedelta(0), timedelta(365))
        )

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.fast_sum = 0.0
        self.slow_sum = 0.0

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(
            self.spy_symbol, self.consolidator
        )

        self.current_slice = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        self.current_slice = slice
        today = self.Time.date()

        if self.held_symbol is not None:
            holding = self.Portfolio[self.held_symbol]

            if today >= self.held_symbol.ID.Date.date():
                self.blocked_entry_date = today
                self.SubmitExit("expiration processing")
            elif holding.Invested:
                self.EvaluateProfitTarget(slice)
                self.EvaluateTimeStop()

        if slice.Bars.ContainsKey(self.spy_symbol):
            self.consolidator.Update(slice.Bars[self.spy_symbol])

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bar_end = bar.EndTime
        bar_time = bar_end.time()

        previous_ready = len(self.slow_values) == 20
        previous_fast = (
            self.fast_sum / len(self.fast_values)
            if self.fast_values else None
        )
        previous_slow = (
            self.slow_sum / len(self.slow_values)
            if self.slow_values else None
        )

        self.fast_values.append(float(bar.Close))
        self.fast_sum = sum(self.fast_values)

        self.slow_values.append(float(bar.Close))
        self.slow_sum = sum(self.slow_values)

        if not previous_ready or len(self.fast_values) < 5:
            return

        current_fast = self.fast_sum / len(self.fast_values)
        current_slow = self.slow_sum / len(self.slow_values)

        bullish_crossover = (
            previous_fast <= previous_slow
            and current_fast > current_slow
        )

        if (
            bullish_crossover
            and time(9, 45) <= bar_time <= time(14, 30)
            and self.Time.date() != self.blocked_entry_date
        ):
            self.TryEnterCall(float(bar.Close))

    def TryEnterCall(self, spy_price: float):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self.IsOrderClosed(
            self.entry_ticket
        ):
            return

        if self.current_slice is None:
            self.Debug("Skipped entry: current Slice unavailable.")
            return

        chain = self.current_slice.OptionChains.get(self.option_symbol)
        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in contracts
            if contract.Expiry.date() == expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            f"Entry submitted: {selected.Symbol} at SPY price {spy_price:.2f}."
        )

    def EvaluateProfitTarget(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and not self.IsOrderClosed(
            self.exit_ticket
        ):
            return

        chain = slice.OptionChains.get(self.option_symbol)
        if chain is None:
            return

        held_contract = next(
            (
                contract for contract in chain
                if contract.Symbol == self.held_symbol
            ),
            None
        )

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrders()
            self.SubmitExit("50% profit target")

    def EvaluateTimeStop(self):
        if self.held_symbol is None:
            return

        expiry_date = self.held_symbol.ID.Date.date()
        if (
            self.Time.date() == expiry_date - timedelta(days=1)
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")

    def SubmitExit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self.IsOrderClosed(
            self.exit_ticket
        ):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol, -quantity
        )
