from datetime import datetime, timedelta, time


class SpyBullishCallAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_key = None
        self._bucket = None

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_price = None

        self.held_option = None
        self.exit_ticket = None
        self.expiration_processing_day = None

    def OnData(self, data: Slice):
        if self.spy not in data.Bars:
            return

        minute_bar = data.Bars[self.spy]
        self._check_expiration_processing(data)
        self._check_time_stop(data)
        self._check_profit_target(data)

        self._consume_minute(minute_bar, data)

    def _consume_minute(self, minute_bar: TradeBar, data: Slice):
        end_time = minute_bar.EndTime
        local_time = end_time.time()

        if local_time <= time(9, 30) or local_time > time(16, 0):
            return

        minutes_from_open = (local_time.hour * 60 + local_time.minute) - (9 * 60 + 30)
        bucket_number = (minutes_from_open + 4) // 5
        bucket_end = datetime(
            end_time.year,
            end_time.month,
            end_time.day,
            9,
            30
        ) + timedelta(minutes=bucket_number * 5)
        bucket_start = bucket_end - timedelta(minutes=5)
        bucket_key = bucket_end

        if self._bucket_key != bucket_key:
            if self._bucket is not None:
                self._finalize_bucket(data)

            self._bucket_key = bucket_key
            self._bucket = {
                "start": bucket_start,
                "end": bucket_end,
                "bars": {}
            }

        self._bucket["bars"][end_time.replace(second=0, microsecond=0)] = minute_bar

        if end_time.replace(second=0, microsecond=0) == bucket_end:
            self._finalize_bucket(data)
            self._bucket_key = None
            self._bucket = None

    def _finalize_bucket(self, data: Slice):
        bucket = self._bucket
        if bucket is None:
            return

        bars = bucket["bars"]

        expected_times = [
            bucket["start"] + timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if any(t not in bars for t in expected_times):
            return

        minute_bars = [bars[t] for t in expected_times]
        consolidated_close = minute_bars[-1].Close

        previous_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if previous_ready else None
        previous_slow = self.slow.Current.Value if previous_ready else None

        self.fast.Update(bucket["end"], consolidated_close)
        self.slow.Update(bucket["end"], consolidated_close)

        if not (previous_ready and self.fast.IsReady and self.slow.IsReady):
            return

        bullish_crossover = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        end_clock = bucket["end"].time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)

        if bullish_crossover and eligible_time:
            self._try_enter(data, consolidated_close)

    def _try_enter(self, data: Slice, spy_price: float):
        if self.expiration_processing_day == self.Time.date():
            return

        if self.held_option is not None:
            return

        if self.entry_ticket is not None and self._is_open(self.entry_ticket):
            return

        chain = None
        try:
            chain = data.OptionChains[self.option_symbol]
        except Exception:
            chain = None

        if chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        minimum_expiry = self.Time.date() + timedelta(days=7)
        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped call selection: no eligible expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped call selection: no eligible call strike.")
            return

        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = self.entry_ticket.OrderId
        self.Debug(
            f"Submitted call entry: {selected.Symbol} "
            f"expiry={selected_expiry} strike={selected.Strike}"
        )

    def _check_profit_target(self, data: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        contract = self._get_contract(data, self.held_option)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _check_time_stop(self, data: Slice):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()
        previous_trading_day = self._previous_trading_day(expiry_date)

        if (
            self.Time.date() == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("expiration time stop")

    def _check_expiration_processing(self, data: Slice):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.expiration_processing_day = self.Time.date()
            self._submit_exit("expiration processing")

    def _submit_exit(self, reason: str):
        if self.held_option is None:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            return

        quantity = int(self.Portfolio[self.held_option].Quantity)
        if quantity <= 0:
            return

        if self.exit_ticket is not None and self._is_open(self.exit_ticket):
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        self.exit_ticket = self.MarketOrder(self.held_option, -quantity)
        self.Debug(f"Submitted call exit: {reason}")

    def _get_contract(self, data: Slice, symbol: Symbol):
        try:
            for chain in data.OptionChains.Values:
                for contract in chain:
                    if contract.Symbol == symbol:
                        return contract
        except Exception:
            pass
        return None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def _is_open(ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending,
            OrderStatus.UpdatePending,
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_option = order_event.Symbol
            self.entry_price = order_event.FillPrice
            self.entry_ticket = None
            self.Debug(
                f"Call entry filled: {self.held_option} "
                f"price={self.entry_price}"
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(f"Call exit filled: {order_event.Symbol}")
            self.held_option = None
            self.entry_price = None
            self.exit_ticket = None

        message = str(order_event.Message).lower()
        if "exercise" in message or "assign" in message:
            self.Debug(f"Unexpected exercise or assignment handling: {order_event.Message}")

    def OnAssignmentOrder(self, assignment_order):
        self.Debug(f"Unexpected assignment handling: {assignment_order}")

