        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption(
            "SPY",
            Resolution.Minute,
            fillForward=False
        )
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 365)
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = RollingWindow[float](self.slow_period)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_start = None
        self.bucket_bars = []

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.held_symbol is not None:
            self._process_expiration(slice, current_date)
            if self.held_symbol is not None:
                self._process_exits(slice, current_date)

        if self.held_symbol is not None:
            return

        if self.expiration_block_date == current_date:
            return

        if self.entry_ticket is not None:
            return

        if not slice.Bars.ContainsKey(self.spy):
            return

        self._update_five_minute_bar(slice.Bars[self.spy], slice)

    def _update_five_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.Time
        local_date = bar_time.date()

        if bar_time.hour < 9 or (bar_time.hour == 9 and bar_time.minute < 30):
            return
        if bar_time.hour > 16 or (bar_time.hour == 16 and bar_time.minute > 0):
            return

        minutes_from_open = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        bucket_minute = (minutes_from_open // 5) * 5
        bucket_start = datetime(
            local_date.year,
            local_date.month,
            local_date.day,
            9,
            30
        ) + timedelta(minutes=bucket_minute)

        if self.bucket_start is None:
            self.bucket_start = bucket_start
        elif bucket_start != self.bucket_start:
            self._emit_bucket(slice)
            self.bucket_start = bucket_start
            self.bucket_bars = []

        if self.bucket_bars:
            expected_time = self.bucket_bars[-1].Time + timedelta(minutes=1)
            if bar_time != expected_time:
                self.bucket_bars = []

        if len(self.bucket_bars) < 5:
            self.bucket_bars.append(minute_bar)

        if len(self.bucket_bars) == 5:
            self._emit_bucket(slice)

    def _emit_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        bars = self.bucket_bars
        self.bucket_bars = []

        if len(bars) != 5:
            return

        for index in range(1, len(bars)):
            if bars[index].Time != bars[index - 1].Time + timedelta(minutes=1):
                return

        consolidated = TradeBar(
            self.bucket_start,
            self.spy,
            bars[0].Open,
            max(bar.High for bar in bars),
            min(bar.Low for bar in bars),
            bars[-1].Close,
            sum(bar.Volume for bar in bars),
            timedelta(minutes=5)
        )

        self._on_consolidated_bar(consolidated, slice)

    def _on_consolidated_bar(self, bar: TradeBar, slice: Slice):
        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        values = list(self.closes)
        fast = sum(values[:self.fast_period]) / self.fast_period
        slow = sum(values[:self.slow_period]) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None and
            self.previous_slow is not None and
            self.previous_fast <= self.previous_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        end_time = bar.EndTime
        if not (time(9, 45) <= end_time.time() <= time(14, 30)):
            return

        if bullish_crossover:
            self._try_enter(slice, float(bar.Close))

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.held_symbol is not None or self.entry_ticket is not None:
            return

        if not slice.OptionChains.ContainsKey(self.option.Symbol):
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option.Symbol]
        current_date = self.Time.date()

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Expiry.date() >= current_date + timedelta(days=7)
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least seven days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _process_exits(self, slice: Slice, current_date):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiration_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        time_stop_date = self._previous_trading_day(expiration_date)

        if current_date == time_stop_date and self.Time.time() >= time(15, 45):
            self._submit_exit("Expiration-eve time stop")
            return

        contract = self._get_current_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _process_expiration(self, slice: Slice, current_date):
        if self.held_symbol is None:
            return

        expiration_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date >= expiration_date:
            self.expiration_block_date = current_date
            self._submit_exit("Expiration processing liquidation")

    def _submit_exit(self, tag):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing open exit order")
            self.exit_ticket = None

        quantity = -holding.Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(
                self.held_symbol,
                quantity,
                tag=tag
            )
            self.Debug("Exit submitted: " + tag)

    def _get_current_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains:
            if chain.Contracts.ContainsKey(symbol):
                return chain.Contracts[symbol]
        return None

    def _previous_trading_day(self, date_value):
        candidate = datetime(
            date_value.year,
            date_value.month,
            date_value.day
        ) - timedelta(days=1)

        exchange_hours = self.Securities[self.spy].Exchange.Hours
        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date()

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_ticket.Symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Entry filled: " +
                    str(self.held_symbol) +
                    " at " +
                    str(self.entry_price)
                )
                self.entry_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Entry order did not fill.")
                self.entry_ticket = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: " + str(self.held_symbol))
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.exit_ticket = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug("Unexpected option exercise or assignment handling.")

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option assignment handling.")

