from datetime import datetime, date, time, timedelta

from QuantConnect import *
from QuantConnect.Algorithm import QCAlgorithm
from QuantConnect.Data import Slice
from QuantConnect.Data.Market import TradeBar
from QuantConnect.Indicators import SimpleMovingAverage
from QuantConnect.Orders import OrderStatus, OrderDirection
from QuantConnect.Securities import DataNormalizationMode, OptionRight, SecurityType


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(timedelta(days=0), timedelta(days=365))
        )
        self.option_canonical = option.Symbol

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_index = None
        self.minute_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration(current_date)
        self._process_option_exit(slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is None:
            return

        self._process_minute_bar(spy_bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        current_date = self.Time.date()
        minute_number = self.Time.hour * 60 + self.Time.minute - (9 * 60 + 30)

        if minute_number < 1 or minute_number > 390:
            return

        bucket_index = (minute_number - 1) // 5

        if self.bucket_date != current_date:
            self.bucket_date = current_date
            self.bucket_index = None
            self.minute_bars = {}

        if self.bucket_index is not None and bucket_index != self.bucket_index:
            self._finalize_bucket(slice)

        if self.bucket_index != bucket_index:
            self.bucket_index = bucket_index
            self.minute_bars = {}

        self.minute_bars[minute_number] = bar

        if minute_number % 5 == 0:
            self._finalize_bucket(slice)

    def _finalize_bucket(self, slice: Slice):
        if not self.minute_bars:
            return

        expected = [
            self.bucket_index * 5 + offset
            for offset in range(1, 6)
        ]

        if not all(minute in self.minute_bars for minute in expected):
            self.minute_bars = {}
            return

        bars = [self.minute_bars[minute] for minute in expected]
        close = bars[-1].Close
        bar_end = self.Time

        was_ready = self.fast.IsReady and self.slow.IsReady
        previous_fast = self.fast.Current.Value if was_ready else None
        previous_slow = self.slow.Current.Value if was_ready else None

        self.fast.Update(bar_end, close)
        self.slow.Update(bar_end, close)

        bullish_crossover = (
            was_ready
            and previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.IsReady
            and self.slow.IsReady
            and self.fast.Current.Value > self.slow.Current.Value
        )

