from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyFiveMinuteCallCrossover(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity("SPY", Resolution.Minute)
        self.spy.SetDataNormalizationMode(DataNormalizationMode.Raw)

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(0, 730)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self.consolidator = TradeBarConsolidator(timedelta(minutes=5))
        self.consolidator.DataConsolidated += self.OnFiveMinuteBar

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self.ProcessExpiration()
        self.ProcessHeldPosition(slice)

        if self.spy.Symbol in slice.Bars:
            bar = slice.Bars[self.spy.Symbol]
            local_end = bar.EndTime

            if time(9, 30) <= local_end.time() <= time(16, 0):
                # Update synchronously so the current Slice is available to the
                # five-minute signal and entry logic.
                self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        local_end = bar.EndTime

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if not bullish_cross:
            return

        if not (time(9, 45) <= local_end.time() <= time(14, 30)):
            return

        self.TryEnterCall(bar.Close)

    def TryEnterCall(self, spy_price):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.entry_ticket is not None:
            return

        if self.held_option is not None:
            return

        if any(
            holding.Symbol.SecurityType == SecurityType.Option
            and holding.Quantity > 0
            for holding in self.Portfolio.Values
        ):
            return

        chains = self.CurrentSlice.OptionChains
        chain = chains.get(self.option.Symbol)

        if chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        minimum_expiry = today + timedelta(days=7)

        expirations = sorted(
            {
                contract.Expiry.date()
                for contract in chain
                if contract.Expiry.date() >= minimum_expiry
            }
        )

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract
            for contract in chain
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.AddOptionContract(selected.Symbol, Resolution.Minute)
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

        self.Debug(
            "Entry submitted: {} strike {:.2f} expiry {}".format(
                selected.Symbol, selected.Strike, selected_expiry
            )
        )

    def ProcessHeldPosition(self, slice: Slice):
        if self.held_option is None:
            return

        holding = self.Portfolio[self.held_option]
        if holding.Quantity <= 0:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration")
            return

        prior_trading_day = self.PreviousTradingDay(expiry_date)

        if (
            self.Time.date() == prior_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("time stop")
            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_option),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrder()
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def CancelOpenExitOrder(self):
        if self.exit_ticket is None:
            return

        status = self.exit_ticket.Status
        if status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.exit_ticket.Cancel("Canceled for higher-priority exit")
            self.exit_ticket = None

    def ProcessExpiration(self):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.Debug("Entry order canceled or invalid.")
                    self.entry_ticket = None
                return

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} at {:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.held_option = None
                    self.entry_price = None
                    self.exit_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.exit_ticket = None
                return

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug(
                "Unexpected option exercise event: {}".format(
                    order_event.Symbol
                )
            )

    def OnAssignmentOrder(self, assignment_event):
        self.Debug(
            "Unexpected option assignment event: {}".format(
                assignment_event.Symbol
            )
        )

