            return

        chain = self.CurrentSlice.OptionChains.get(self.option.Symbol)
        if chain is None:
            return

        contract = next(
            (item for item in chain if item.Symbol == self.held_option),
            None
        )

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0

        if self.entry_price is not None and midpoint >= 1.5 * self.entry_price:
            self.CancelOpenExitOrder()
            self.SubmitExit("profit target")

    def SubmitExit(self, reason):
        if self.held_option is None:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                return

        quantity = self.Portfolio[self.held_option].Quantity
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: {} ({})".format(self.held_option, reason))

    def CancelOpenExitOrder(self):
        if self.exit_ticket is None:
            return

        status = self.exit_ticket.Status
        if status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
        ):
            self.exit_ticket.Cancel("Canceled for higher-priority exit")
            self.exit_ticket = None

    def ProcessExpiration(self):
        if self.held_option is None:
            return

        expiry_date = self.Securities[self.held_option].Symbol.ID.Date.date()

        if self.Time.date() >= expiry_date:
            self.blocked_entry_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while not hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)

        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None:
            if order_event.OrderId == self.entry_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.held_option = order_event.Symbol
                    self.entry_price = order_event.FillPrice
                    self.Debug(
                        "Entry filled: {} at {:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
                    self.entry_ticket = None
                elif order_event.Status in (
                    OrderStatus.Canceled,
                    OrderStatus.Invalid,
                ):
                    self.Debug("Entry order canceled or invalid.")
                    self.entry_ticket = None
                return

        if self.exit_ticket is not None:
            if order_event.OrderId == self.exit_ticket.OrderId:
                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Exit filled: {} at {:.4f}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )
