from AlgorithmImports import *
from collections import deque
from datetime import datetime, timedelta


class SpyLongCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        self.option = self.AddOption("SPY", Resolution.Minute)
        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-1000, 1000)
                .Expiration(0, 730)
        )
        self.option_symbol = self.option.Symbol

        self.fast_closes = deque(maxlen=5)
        self.slow_closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.current_bucket_start = None
        self.current_bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.pending_entry_symbol = None

        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.expiration_day_blocked = set()

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never open or retain a position on the contract's expiration date.
        if self.held_symbol is not None and self.expiration_date == today:
            self.expiration_day_blocked.add(today)
            if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
                self.entry_ticket.Cancel("Expiration-day protection")
            self._submit_exit("Expiration-day liquidation")
            return

        if self.pending_entry_symbol is not None and today in self.expiration_day_blocked:
            if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
                self.entry_ticket.Cancel("Entry blocked on expiration date")
            return

        if self.held_symbol is not None:
            self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._accept_minute_bar(bar, slice)

    def _accept_minute_bar(self, bar: TradeBar, slice: Slice):
        start = bar.Time.replace(
            minute=(bar.Time.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.current_bucket_start is None:
            self.current_bucket_start = start

        if start != self.current_bucket_start:
            self.current_bucket_start = start
            self.current_bucket_bars = {}

        self.current_bucket_bars[bar.Time] = bar

        expected_times = [
            self.current_bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.current_bucket_bars for t in expected_times):
            return

        bars = [self.current_bucket_bars[t] for t in expected_times]
        consolidated_close = bars[-1].Close
        consolidated_end = self.current_bucket_start + timedelta(minutes=5)

        self._process_five_minute_bar(
            consolidated_close,
            consolidated_end,
            slice
        )

        self.current_bucket_start = None
        self.current_bucket_bars = {}

    def _process_five_minute_bar(self, close, bar_end, slice: Slice):
        if len(self.fast_closes) == 5 and len(self.slow_closes) == 20:
            self.previous_fast = sum(self.fast_closes) / 5.0
            self.previous_slow = sum(self.slow_closes) / 20.0

        self.fast_closes.append(close)
        self.slow_closes.append(close)

        if len(self.fast_closes) < 5 or len(self.slow_closes) < 20:
            return

        current_fast = sum(self.fast_closes) / 5.0
        current_slow = sum(self.slow_closes) / 20.0

        bullish_cross = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            bar_end.hour > 9
            or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14
            or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish_cross and eligible_time:
            self._try_enter(slice, close)

        self.previous_fast = current_fast
        self.previous_slow = current_slow

    def _try_enter(self, slice: Slice, spy_price):
        today = self.Time.date()

        if today in self.expiration_day_blocked:
            return

        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and self.entry_ticket.Status.IsOpen():
            return

        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        minimum_expiry = today + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no qualifying expiration.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in chain
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (
                float(contract.Strike),
                str(contract.Symbol)
            )
        )[0]

        self.pending_entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol,
                selected_expiry,
                selected.Strike
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        today = self.Time.date()
        now = self.Time

        # Time stop applies independently of option quotes.
        if (
            self.time_stop_date == today
            and now.hour == 15
            and now.minute >= 45
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.option_symbol not in slice.OptionChains:
            return

        held_contract = None
        for contract in slice.OptionChains[self.option_symbol]:
            if contract.Symbol == self.held_symbol:
                held_contract = contract
                break

        if held_contract is None:
            return

        bid = float(held_contract.BidPrice)
        ask = float(held_contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and self.exit_ticket.Status.IsOpen():
            self.exit_ticket.Cancel("Replacing exit: " + reason)

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(
                self.held_symbol,
                reason
            )
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if getattr(order_event, "IsAssignment", False):
            self.Debug(
                "Unexpected option assignment/exercise: {0}".format(
                    order_event
                )
            )

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.held_symbol = self.pending_entry_symbol
                self.entry_price = float(order_event.FillPrice)
                self.expiration_date = self.held_symbol.ID.Date.date()
                self.time_stop_date = self._previous_trading_day(
                    self.expiration_date
                )
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                if order_event.Status != OrderStatus.Filled:
                    self.pending_entry_symbol = None
                    self.entry_ticket = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug(
                "Exit filled: {0} at {1}".format(
                    self.held_symbol,
                    order_event.FillPrice
                )
            )
            self._clear_position_state()

    def OnEndOfAlgorithm(self):
        if self.held_symbol is not None:
            self.Debug(
                "Unexpected remaining option position at algorithm end: {0}".format(
                    self.held_symbol
                )
            )

    def _clear_position_state(self):
        self.held_symbol = None
        self.entry_price = None
        self.expiration_date = None
        self.time_stop_date = None
        self.exit_ticket = None
        self.entry_ticket = None
        self.pending_entry_symbol = None

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

