        self.consolidator.DataConsolidated += self.OnFiveMinuteBar
        self.SubscriptionManager.AddConsolidator(self.spy, self.consolidator)

        self.pending_signal = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.held_option = None
        self.entry_price = None
        self.no_entry_date = None

    def OnFiveMinuteBar(self, sender, bar):
        bar_time = bar.EndTime
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        self.fast_values.Add(self.fast.Current.Value)
        self.slow_values.Add(self.slow.Current.Value)

        if not self.fast.IsReady or not self.slow.IsReady:
            return

        if not self.fast_values.IsReady or not self.slow_values.IsReady:
            return

        bullish_crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        bar_clock = bar_time.time()
        if bullish_crossover and (
            bar_clock >= time(9, 45) and bar_clock <= time(14, 30)
        ):
            self.pending_signal = (bar.EndTime, float(bar.Close))

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.held_option is not None:
            expiry_date = self.held_option.ID.Date.date()

            if today >= expiry_date:
                self.no_entry_date = today
                self.SubmitExit("expiration processing")
            else:
                prior_trading_day = self.PreviousTradingDay(expiry_date)
                if today == prior_trading_day and self.Time.time() >= time(15, 45):
                    self.SubmitExit("expiration time stop")
                else:
                    self.CheckProfitTarget(slice)

        if self.pending_signal is not None:
            signal_time, spy_price = self.pending_signal
            self.pending_signal = None
            self.TryEnter(slice, spy_price)

    def TryEnter(self, slice: Slice, spy_price: float):
        today = self.Time.date()

        if today == self.no_entry_date:
            return

        if self.held_option is not None:
            return

        if self.IsOrderOpen(self.entry_ticket):
            return

        if slice.OptionChains is None or len(slice.OptionChains) == 0:
            self.Debug("Skipped entry: no option chain")
            return

        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue

                expiry_date = contract.Expiry.date()
                if expiry_date >= minimum_expiry:
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying expiration")
            return

        selected_expiry = min(contract.Expiry.date() for contract in candidates)
        strike_floor = 1.01 * spy_price

        strike_candidates = [
            contract
            for contract in candidates
            if contract.Expiry.date() == selected_expiry
            and contract.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike")
            return

        selected = min(
            strike_candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )
        self.held_option = selected.Symbol
        self.entry_price = None

    def CheckProfitTarget(self, slice: Slice):
        if self.held_option is None or self.entry_price is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        quote = self.GetCurrentOptionQuote(slice, self.held_option)
        if quote is None:
            return

        bid, ask = quote
        midpoint = (bid + ask) / 2.0

        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def SubmitExit(self, reason: str):
        if self.held_option is None:
            return

        if self.IsOrderOpen(self.exit_ticket):
            return

        if self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket):
            self.entry_ticket.Cancel("Exit requested")

        holding = self.Portfolio[self.held_option]
        quantity = holding.Quantity

        if quantity == 0:
            self.held_option = None
            self.entry_price = None
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel("Replacing prior exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_option,
            -quantity,
            tag=reason
        )

    def GetCurrentOptionQuote(self, slice: Slice, symbol: Symbol):
        if slice.OptionChains is None:
            return None

        for chain in slice.OptionChains.Values:
            for contract in chain:
                if contract.Symbol != symbol:
                    continue

                bid = float(contract.BidPrice)
                ask = float(contract.AskPrice)

                if bid > 0 and ask > 0:
                    return bid, ask

                return None

        return None

    def PreviousTradingDay(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def IsOrderOpen(self, ticket):
        if ticket is None:
            return False

        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    f"Entered {self.held_option} at {self.entry_price:.4f}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Entry order did not fill")
                self.entry_ticket = None
                self.held_option = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exited {self.held_option}: {self.exit_ticket.Tag}")
                self.exit_ticket = None
                self.held_option = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment received")

