from collections import deque
from datetime import datetime, time, timedelta


class SpyBullishCallAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-100, 100)
                .Expiration(0, 365)
        )
        self.option_canonical = self.spy_option.Symbol

        self.closes = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.held_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_date = None
        self.no_entry_date = None

    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        if self.held_symbol is not None and self.expiration_date is not None:
            if current_date >= self.expiration_date:
                self.no_entry_date = current_date
                self._submit_exit("expiration protection")

        self._evaluate_time_stop(current_date, slice)

        spy_bar = slice.Bars.get(self.spy)
        if spy_bar is not None:
            signal, bar_end = self._process_spy_minute(spy_bar)
            if signal and time(9, 45) <= bar_end.time() <= time(14, 30):
                self._try_entry(slice, spy_bar.Close)

        self._evaluate_profit_target(slice)

    def _process_spy_minute(self, bar):
        end = bar.EndTime
        local_date = end.date()
        session_start = datetime.combine(local_date, time(9, 30))
        session_end = datetime.combine(local_date, time(16, 0))

        if end <= session_start or end > session_end:
            return False, end

        elapsed_minutes = int((end - session_start).total_seconds() / 60)
        if elapsed_minutes <= 0:
            return False, end

        bucket_index = (elapsed_minutes - 1) // 5
        bucket_end = session_start + timedelta(minutes=(bucket_index + 1) * 5)

        bucket_changed = (
            self.bucket_date != local_date or
            self.bucket_end != bucket_end
        )

        if bucket_changed:
            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[end] = bar

        if end != bucket_end:
            return False, end

        expected_times = [
            bucket_end - timedelta(minutes=i) for i in range(5, 0, -1)
        ]
        complete = all(t in self.bucket_bars for t in expected_times)

        consolidated = None
        if complete:
            bars = [self.bucket_bars[t] for t in expected_times]
            consolidated = TradeBar(
                Symbol=self.spy,
                Time=bars[0].Time,
                Period=timedelta(minutes=5),
                Open=bars[0].Open,
                High=max(b.High for b in bars),
                Low=min(b.Low for b in bars),
                Close=bars[-1].Close,
                Volume=sum(b.Volume for b in bars)
            )

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        if consolidated is None:
            return False, bucket_end

        signal = self._update_averages(consolidated.Close)
        return signal, bucket_end

    def _update_averages(self, close):
        old_fast = self.previous_fast
        old_slow = self.previous_slow

        self.closes.append(float(close))
        if len(self.closes) < 20:
            return False

        fast = sum(list(self.closes)[-5:]) / 5.0
        slow = sum(self.closes) / 20.0

        signal = (
            old_fast is not None and
            old_slow is not None and
            old_fast <= old_slow and
            fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow
        return signal

    def _try_entry(self, slice, spy_price):
        if self.no_entry_date == self.Time.date():
            return

        if self.held_symbol is not None or self._has_option_holding():
            return

        if self._entry_order_is_open():
            return

        if spy_price is None or spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        chains = self._get_option_chains(slice)
        if not chains:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        candidates = []
        for chain in chains:
            for contract in chain:
                expiry = self._as_date(contract.Expiry)
                if expiry < minimum_expiry:
                    continue
                if contract.Right != OptionRight.Call:
                    continue
                if contract.Strike < 1.01 * spy_price:
                    continue
                candidates.append(contract)

        if not candidates:
            self.Debug("Skipped call selection: no eligible expiration or strike.")
            return

        candidates.sort(
            key=lambda c: (
                self._as_date(c.Expiry),
                float(c.Strike),
                str(c.Symbol)
            )
        )
        selected = candidates[0]
        selected_symbol = selected.Symbol

        self.AddOptionContract(selected_symbol, Resolution.Minute)

        self.entry_symbol = selected_symbol
        self.expiration_date = self._as_date(selected.Expiry)
        self.entry_ticket = self.MarketOrder(
            selected_symbol,
            1,
            tag="Bullish SPY five-minute crossover entry"
        )

    def _evaluate_profit_target(self, slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        if self.Portfolio[self.held_symbol].Quantity <= 0:
            return

        quote = self._get_current_option_quote(slice, self.held_symbol)
        if quote is None:
            return

        bid, ask = quote
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _evaluate_time_stop(self, current_date, slice):
        if self.held_symbol is None or self.expiration_date is None:
            return

        previous_trading_day = self._previous_trading_day(self.expiration_date)
        if (
            current_date == previous_trading_day and
            self.Time.time() >= time(15, 45)
        ):
            self._submit_exit("pre-expiration time stop")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (
                OrderStatus.New,
                OrderStatus.Submitted,
                OrderStatus.PartiallyFilled
            ):
                self.exit_ticket.Cancel("Replaced by liquidation order")
            self.exit_ticket = None

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug(
            "Exit submitted: {0} ({1})".format(self.held_symbol, reason)
        )

    def _get_current_option_quote(self, slice, symbol):
        for chain in self._get_option_chains(slice):
            for contract in chain:
                if contract.Symbol == symbol:
                    return float(contract.BidPrice), float(contract.AskPrice)
        return None

    def _get_option_chains(self, slice):
        try:
            return list(slice.OptionChains.Values)
        except Exception:
            try:
                return list(slice.OptionChains.values())
            except Exception:
                return []

    def _entry_order_is_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _has_option_holding(self):
        for holding in self.Portfolio.Values:
            if (
                holding.Invested and
                holding.Symbol.SecurityType == SecurityType.Option
            ):
                return True
        return False

    def _previous_trading_day(self, date_value):
        candidate = date_value - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate

    def _as_date(self, value):
        if hasattr(value, "date"):
            return value.date()
        return value

    def OnOrderEvent(self, order_event):
        if (
            self.entry_ticket is not None and
            order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.held_symbol = self.entry_symbol
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.expiration_date = None

        if (
            self.exit_ticket is not None and
            order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Call position exited: {0} at {1}".format(
                        order_event.Symbol, order_event.FillPrice
                    )
                )
                self.exit_ticket = None
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None
                self.expiration_date = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        if order_event.Status == OrderStatus.Filled:
            try:
                if order_event.OrderType == OrderType.OptionExercise:
                    self.Debug(
                        "Unexpected option exercise detected for {0}."
                        .format(order_event.Symbol)
                    )
            except Exception:
                pass

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug(
            "Unexpected option assignment detected: {0}".format(
                assignment_event
            )
        )

