        candidates.sort(key=lambda contract: (contract.Strike, str(contract.Symbol)))
        selected = candidates[0]

        self.entry_symbol = selected.Symbol
        self.entry_order_id = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        ).OrderId

    def ProcessProfitTarget(self, slice: Slice):
        held = self.GetHeldOption()
        if held is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        contract = self.GetContractFromSlice(slice, held)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.CancelOpenExitOrder()
            quantity = -self.Portfolio[held].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    held,
                    quantity,
                    tag="50 percent option profit target"
                )

    def ProcessTimeStop(self):
        held = self.GetHeldOption()
        if held is None:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            return

        expiry = self.Securities[held].Symbol.ID.Date.date()
        if self.IsPreviousTradingDay(self.Time.date(), expiry):
            self.CancelOpenExitOrder()
            quantity = -self.Portfolio[held].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    held,
                    quantity,
                    tag="Expiration-eve time stop"
                )

    def ProcessExpiration(self):
        self.blocked_entry_date = self.Time.date()

        if self.entry_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.entry_order_id)
            if ticket is not None and self.IsOrderOpen(ticket):
                ticket.Cancel("Expiration processing began")
            self.entry_order_id = None

        held = self.GetHeldOption()
        if held is None:
            return

        expiry = self.Securities[held].Symbol.ID.Date.date()
        if expiry == self.Time.date():
            self.CancelOpenExitOrder()
            quantity = -self.Portfolio[held].Quantity
            if quantity != 0:
                self.exit_ticket = self.MarketOrder(
                    held,
                    quantity,
                    tag="Expiration-day liquidation"
                )

    def OnOrderEvent(self, order_event: OrderEvent):
        order = self.Transactions.GetOrderById(order_event.OrderId)
        if order is not None:
            if getattr(order_event, "IsAssignment", False):
                self.Debug("Unexpected option assignment or exercise detected.")
            if order.Type == OrderType.OptionExercise:
                self.Debug("Unexpected option exercise detected.")

        if self.entry_order_id == order_event.OrderId:
            if order_event.Status in (OrderStatus.PartiallyFilled, OrderStatus.Filled):
                if order_event.FillQuantity > 0:
                    if self.entry_price is None:
                        self.entry_price = float(order_event.FillPrice)
                    else:
                        old_quantity = self.Portfolio[order_event.Symbol].Quantity - order_event.FillQuantity
                        if old_quantity > 0:
                            self.entry_price = (
                                self.entry_price * old_quantity +
                                float(order_event.FillPrice) * order_event.FillQuantity
                            ) / self.Portfolio[order_event.Symbol].Quantity

                    self.Debug(
                        "Entered SPY call {0} at {1}".format(
                            order_event.Symbol, order_event.FillPrice
                        )
                    )

            if order_event.Status in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_order_id = None

        if self.exit_ticket is not None and self.exit_ticket.OrderId == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exited SPY call {0} at {1}".format(
                    order_event.Symbol, order_event.FillPrice
                ))
                self.exit_ticket = None
                self.entry_symbol = None
                self.entry_price = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

    def GetHeldOption(self):
        for security in self.Portfolio:
            if security.Value.Invested and security.Key.SecurityType == SecurityType.Option:
                return security.Key
        return None

    def GetCurrentOptionChain(self, slice):
        for chain in slice.OptionChains.Values:
            if chain.Symbol == self.option.Symbol:
                return chain
        return None

    def GetContractFromSlice(self, slice, symbol):
        for chain in slice.OptionChains.Values:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def CancelOpenExitOrder(self):
        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

    def IsOrderOpen(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def IsPreviousTradingDay(self, current_date, expiry_date):
        candidate = expiry_date - timedelta(days=1)
        while candidate >= current_date - timedelta(days=10):
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(candidate.year, candidate.month, candidate.day)
            ):
                return current_date == candidate
            candidate -= timedelta(days=1)
        return False

    def OnEndOfAlgorithm(self):
        self.SubscriptionManager.RemoveConsolidator(self.spy, self.consolidator)

