            if quote is not None and quote.Bid is not None and quote.Ask is not None:
                bid = float(quote.Bid.Close)
                ask = float(quote.Ask.Close)
                if bid > 0 and ask > 0:
                    midpoint = (bid + ask) / 2.0
                    profit_target = midpoint >= 1.50 * self.entry_price

        if profit_target or time_stop:
            reason = "profit target" if profit_target else "expiration time stop"
            self._submit_exit(reason)

    def _process_expiration_day(self, slice: Slice, today):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if today != expiry_date:
            return

        self.expiration_blocked_date = today

        if self.Portfolio[self.held_symbol].Invested and not self._exit_order_is_open():
            self._submit_exit("expiration-day liquidation")
            self.Debug("Unexpected option position at expiration; liquidating.")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_is_terminal(self.exit_ticket):
            return

        for ticket in [self.exit_ticket]:
            if ticket is not None and not self._ticket_is_terminal(ticket):
                ticket.Cancel("Replacing open exit order")

        quantity = -self.Portfolio[self.held_symbol].Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.held_symbol, quantity)
            self.Debug("Exit submitted: " + reason)

    def _is_trading_day_immediately_before(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        next_date = current_date + timedelta(days=1)
        while next_date < expiry_date:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(
                datetime(next_date.year, next_date.month, next_date.day)
            ):
                return False
            next_date += timedelta(days=1)

        return next_date == expiry_date

    def _entry_order_is_open(self):
        return (
            self.entry_ticket is not None
            and not self._ticket_is_terminal(self.entry_ticket)
        )

    def _exit_order_is_open(self):
        return (
            self.exit_ticket is not None
            and not self._ticket_is_terminal(self.exit_ticket)
        )

    @staticmethod
    def _ticket_is_terminal(ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Call entry filled: "
                + str(self.held_symbol)
                + " at "
                + str(self.entry_price)
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call position exit filled.")

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug("Unexpected option exercise or assignment received.")

