            return

        end_minute = self.bucket_end.hour * 60 + self.bucket_end.minute
        expected_minutes = {end_minute - i for i in range(5)}

        if set(self.bucket_bars.keys()) != expected_minutes:
            self.bucket_end = None
            self.bucket_bars = {}
            return

        close = self.bucket_bars[end_minute].Close
        bar_end = self.bucket_end

        self.fast_values.Add(float(close))
        self.slow_values.Add(float(close))

        bullish_cross = False
        if self.fast_values.IsReady and self.slow_values.IsReady:
            fast = sum(self.fast_values[i] for i in range(self.fast_period)) / self.fast_period
            slow = sum(self.slow_values[i] for i in range(self.slow_period)) / self.slow_period

            if self.previous_fast is not None and self.previous_slow is not None:
                bullish_cross = (
                    self.previous_fast <= self.previous_slow
                    and fast > slow
                )

            self.previous_fast = fast
            self.previous_slow = slow

        self.bucket_end = None
        self.bucket_bars = {}

        if not bullish_cross:
            return

        if not (datetime.strptime("09:45", "%H:%M").time()
                <= bar_end.time()
                <= datetime.strptime("14:30", "%H:%M").time()):
