        if current_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if (expiry_date - today).days >= 7:
                    eligible_expirations.append(expiry_date)

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(eligible_expirations)
        minimum_strike = current_spy_price * 1.01
        candidates = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Expiry.date() == selected_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

    def _manage_position(self, data: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.expiration_block_date = today
            self._submit_exit("expiration processing")
            return

        if (
            today == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self.entry_price is None or self._exit_order_open():
            return

        contract = None
        for chain in data.OptionChains.Values:
            candidate = chain.Contracts.get(self.entry_symbol)
            if candidate is not None:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        quantity = holding.Quantity
        if quantity == 0 or self._exit_order_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel()

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _has_option_holding(self):
        for security in self.Portfolio.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and security.Invested
            ):
                return True
        return False

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
