        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        self.spy = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.spy_option.SetFilter(
            lambda universe: universe
            .IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.fast_values = RollingWindow[float](self.fast_period)
        self.slow_values = RollingWindow[float](self.slow_period)

        self.bucket_end = None
        self.bucket_bars = {}
        self.previous_fast = None
        self.previous_slow = None

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None
        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, data: Slice):
        self._manage_position(data)

        spy_bar = data.Bars.get(self.spy)
        if spy_bar is None:
            return

        bar_time = spy_bar.EndTime
        if bar_time.tzinfo is not None:
            bar_time = bar_time.replace(tzinfo=None)

        if self.bucket_end is not None and bar_time.date() != self.bucket_end.date():
            self.bucket_end = None
            self.bucket_bars = {}

        if bar_time.time() < datetime.strptime("09:31", "%H:%M").time():
            return
        if bar_time.time() > datetime.strptime("16:00", "%H:%M").time():
            return

        minute_number = bar_time.hour * 60 + bar_time.minute
        bucket_minute = ((minute_number + 4) // 5) * 5
        bucket_date = bar_time.date()
        bucket_hour = bucket_minute // 60
        bucket_minute_of_hour = bucket_minute % 60
        new_bucket_end = datetime(
            bucket_date, bar_time.time().replace(
                hour=bucket_hour,
                minute=bucket_minute_of_hour,
                second=0,
                microsecond=0
            ).hour,
            bucket_minute_of_hour
        )

        if self.bucket_end is not None and new_bucket_end != self.bucket_end:
            self._complete_bucket()

        if self.bucket_end is None:
            self.bucket_end = new_bucket_end
            self.bucket_bars = {}

        self.bucket_bars[bar_time.hour * 60 + bar_time.minute] = spy_bar

        if len(self.bucket_bars) == 5:
            self._complete_bucket()

    def _complete_bucket(self):
        if self.bucket_end is None:
            return

        end_minute = self.bucket_end.hour * 60 + self.bucket_end.minute
        expected_minutes = {end_minute - i for i in range(5)}

        if set(self.bucket_bars.keys()) != expected_minutes:
            self.bucket_end = None
            self.bucket_bars = {}
            return

        close = self.bucket_bars[end_minute].Close
        bar_end = self.bucket_end

        self.fast_values.Add(float(close))
        self.slow_values.Add(float(close))

        bullish_cross = False
        if self.fast_values.IsReady and self.slow_values.IsReady:
            fast = sum(self.fast_values[i] for i in range(self.fast_period)) / self.fast_period
            slow = sum(self.slow_values[i] for i in range(self.slow_period)) / self.slow_period

            if self.previous_fast is not None and self.previous_slow is not None:
                bullish_cross = (
                    self.previous_fast <= self.previous_slow
                    and fast > slow
                )

            self.previous_fast = fast
            self.previous_slow = slow

        self.bucket_end = None
        self.bucket_bars = {}

        if not bullish_cross:
            return

        if not (datetime.strptime("09:45", "%H:%M").time()
                <= bar_end.time()
                <= datetime.strptime("14:30", "%H:%M").time()):
            return

        if self.expiration_block_date == self.Time.date():
            return

        self._try_enter(bar_end)

    def _try_enter(self, bar_end):
        if self._has_option_holding() or self._entry_order_open():
            return

        current_spy_price = self.Securities[self.spy].Price
        if current_spy_price <= 0:
            self.Debug("Skipped entry: invalid SPY price.")
            return

        chains = list(self.CurrentSlice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        today = self.Time.date()
        eligible_expirations = []

        for chain in chains:
            for contract in chain:
                expiry_date = contract.Expiry.date()
                if (expiry_date - today).days >= 7:
                    eligible_expirations.append(expiry_date)

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = min(eligible_expirations)
        minimum_strike = current_spy_price * 1.01
        candidates = []

        for chain in chains:
            for contract in chain:
                if (
                    contract.Expiry.date() == selected_expiry
                    and contract.Right == OptionRight.Call
                    and contract.Strike >= minimum_strike
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_ticket = self.MarketOrder(
            self.entry_symbol,
            1,
            tag="Bullish five-minute SMA crossover"
        )

    def _manage_position(self, data: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        today = self.Time.date()

        if today >= expiry_date:
            self.expiration_block_date = today
            self._submit_exit("expiration processing")
            return

        if (
            today == expiry_date - timedelta(days=1)
            and self.Time.hour == 15
            and self.Time.minute >= 45
        ):
            self._submit_exit("expiration time stop")
            return

        if self.entry_price is None or self._exit_order_open():
            return

        contract = None
        for chain in data.OptionChains.Values:
            candidate = chain.Contracts.get(self.entry_symbol)
            if candidate is not None:
                contract = candidate
                break

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.5 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        quantity = holding.Quantity
        if quantity == 0 or self._exit_order_open():
            return

        if self.exit_ticket is not None:
            self.exit_ticket.Cancel()

        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _has_option_holding(self):
        for security in self.Portfolio.Values:
            if (
                security.Symbol.SecurityType == SecurityType.Option
                and security.Invested
            ):
                return True
        return False

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False
        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def _exit_order_open(self):
        if self.exit_ticket is None:
            return False
        return self.exit_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.FillQuantity > 0:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Call entry filled: "
                    + str(order_event.Symbol)
                    + " at "
                    + str(order_event.FillPrice)
                )

            if order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected
            ):
                self.Debug("Call entry order did not fill.")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call position exited: " + str(order_event.Symbol))
            self.exit_ticket = None
            self.entry_ticket = None
            self.entry_symbol = None
            self.entry_price = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected option exercise or assignment: "
            + str(assignment_event.Symbol)
        )

