from AlgorithmImports import *
from collections import deque
from datetime import timedelta


class SpyCallCrossoverAlgorithm(QCAlgorithm):
    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe.IncludeWeeklys()
            .Strikes(-500, 500)
            .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_values = deque(maxlen=5)
        self.slow_values = deque(maxlen=20)
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_date = None
        self.bucket_end = None
        self.bucket_bars = {}

        self.latest_spy_price = None
        self.held_symbol = None
        self.entry_ticket = None
        self.exit_ticket = None
        self.entry_price = None

        self.expiration_processed_date = None
        self.last_holding_symbol = None

    def OnData(self, data: Slice):
        current_date = self.Time.date()

        if self.spy in data.Bars:
            spy_bar = data.Bars[self.spy]
            self.latest_spy_price = float(spy_bar.Close)
            self._process_minute_bar(spy_bar, data)

        self._process_expiration(current_date)
        self._manage_open_position(data, current_date)

        if (
            self.last_holding_symbol is not None
            and self.held_symbol == self.last_holding_symbol
            and not self.Portfolio[self.last_holding_symbol].Invested
            and self.exit_ticket is None
            and self.entry_ticket is None
        ):
            self.Debug("Unexpected exercise or assignment handling for {}".format(
                self.last_holding_symbol
            ))
            self.held_symbol = None
            self.entry_price = None

        if self.held_symbol is not None:
            self.last_holding_symbol = self.held_symbol

    def _process_minute_bar(self, bar: TradeBar, data: Slice):
        minute_start = bar.EndTime - timedelta(minutes=1)
        local_date = minute_start.date()
        session_start = minute_start.replace(hour=9, minute=30, second=0, microsecond=0)
        session_end = minute_start.replace(hour=16, minute=0, second=0, microsecond=0)

        if minute_start < session_start or minute_start >= session_end:
            return

        elapsed_minutes = int((minute_start - session_start).total_seconds() // 60)
        bucket_index = elapsed_minutes // 5
        bucket_end = session_start + timedelta(minutes=(bucket_index + 1) * 5)

        if self.bucket_date != local_date or self.bucket_end != bucket_end:
            if self.bucket_date == local_date and self.bucket_bars:
                self._complete_bucket(data)

            self.bucket_date = local_date
            self.bucket_end = bucket_end
            self.bucket_bars = {}

        self.bucket_bars[minute_start] = bar

        if len(self.bucket_bars) == 5:
            self._complete_bucket(data)

    def _complete_bucket(self, data: Slice):
        if self.bucket_end is None or len(self.bucket_bars) != 5:
            self.bucket_bars = {}
            return

        expected = [
            self.bucket_end - timedelta(minutes=i)
            for i in range(1, 6)
        ]

        if set(self.bucket_bars.keys()) != set(expected):
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in sorted(expected)]
        consolidated = TradeBar(
            self.bucket_end - timedelta(minutes=5),
            self.spy,
            bars[0].Open,
            max(float(x.High) for x in bars),
            min(float(x.Low) for x in bars),
            bars[-1].Close,
            sum(int(x.Volume) for x in bars),
            timedelta(minutes=5)
        )

        self.bucket_bars = {}
        self._on_consolidated_bar(consolidated, data)

    def _on_consolidated_bar(self, bar: TradeBar, data: Slice):
        self.fast_values.append(float(bar.Close))
        self.slow_values.append(float(bar.Close))

        if len(self.fast_values) < 5 or len(self.slow_values) < 20:
            self.previous_fast = None
            self.previous_slow = None
            return

        fast = sum(self.fast_values) / 5.0
        slow = sum(self.slow_values) / 20.0

        bullish = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and fast > slow
        )

        self.previous_fast = fast
        self.previous_slow = slow

        bar_end = bar.EndTime
        eligible_time = (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            return

        if self.latest_spy_price is None:
            self.Debug("Skipped selection: SPY price unavailable")
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped selection: option chain unavailable")
            return

        chain = data.OptionChains[self.option_symbol]
        contracts = list(chain.Contracts.Values)
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * self.latest_spy_price

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _manage_open_position(self, data: Slice, current_date):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._submit_exit("expiration")
            return

        prior_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == prior_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("time stop")
            return

        if self.held_symbol not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_symbol]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit()
        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date >= expiry_date and self.expiration_processed_date != current_date:
            self.expiration_processed_date = current_date
            self._submit_exit("expiration processing")

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_symbol = orderEvent.Symbol
                self.entry_price = float(orderEvent.FillPrice)
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
                OrderStatus.PartiallyFilled,
            ) and orderEvent.Status != OrderStatus.PartiallyFilled:
                self.Debug("Entry order did not fill: {}".format(orderEvent.Status))
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {}".format(
                    orderEvent.Symbol, orderEvent.FillPrice
                ))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignmentEvent: OrderEvent):
        self.Debug("Unexpected option assignment: {}".format(assignmentEvent.Symbol))

    def _cancel_open_exit(self):
        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")
            self.exit_ticket = None

    def _ticket_done(self, ticket):
        return ticket is None or ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid,
            OrderStatus.Error,
        )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)

        return candidate.date() if hasattr(candidate, "date") else candidate.date()

