        bar_end = bar.EndTime
        eligible_time = (
            bar_end.hour > 9 or (bar_end.hour == 9 and bar_end.minute >= 45)
        ) and (
            bar_end.hour < 14 or (bar_end.hour == 14 and bar_end.minute <= 30)
        )

        if bullish and eligible_time:
            self._try_enter(data)

    def _try_enter(self, data: Slice):
        if self.held_symbol is not None:
            return

        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            return

        if self.latest_spy_price is None:
            self.Debug("Skipped selection: SPY price unavailable")
            return

        if self.option_symbol not in data.OptionChains:
            self.Debug("Skipped selection: option chain unavailable")
            return

        chain = data.OptionChains[self.option_symbol]
        contracts = list(chain.Contracts.Values)
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expiries = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() >= minimum_expiry
        })

        if not expiries:
            self.Debug("Skipped selection: no qualifying expiration")
            return

        selected_expiry = expiries[0]
        minimum_strike = 1.01 * self.latest_spy_price

        candidates = [
            contract for contract in contracts
            if contract.Right == OptionRight.Call
            and contract.Expiry.date() == selected_expiry
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped selection: no qualifying call strike")
            return

        selected = sorted(
            candidates,
            key=lambda contract: (float(contract.Strike), str(contract.Symbol))
        )[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug("Entry submitted: {}".format(selected.Symbol))

