            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if current_date >= expiry_date:
            self._submit_exit("expiration")
            return

        prior_trading_day = self._previous_trading_day(expiry_date)
        if (
            current_date == prior_trading_day
            and self.Time.hour == 15
            and self.Time.minute == 45
        ):
            self._submit_exit("time stop")
            return

        if self.held_symbol not in data.QuoteBars:
            return

        quote = data.QuoteBars[self.held_symbol]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("profit target")

    def _submit_exit(self, reason):
        if self.held_symbol is None:
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity <= 0:
            return

        self._cancel_open_exit()
        self.exit_ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _process_expiration(self, current_date):
        if self.held_symbol is None:
            return

        expiry_date = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if current_date >= expiry_date and self.expiration_processed_date != current_date:
            self.expiration_processed_date = current_date
            self._submit_exit("expiration processing")

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.held_symbol = orderEvent.Symbol
                self.entry_price = float(orderEvent.FillPrice)
                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
                OrderStatus.PartiallyFilled,
            ) and orderEvent.Status != OrderStatus.PartiallyFilled:
                self.Debug("Entry order did not fill: {}".format(orderEvent.Status))
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {} at {}".format(
                    orderEvent.Symbol, orderEvent.FillPrice
                ))
                self.held_symbol = None
                self.entry_price = None
                self.exit_ticket = None
                self.entry_ticket = None
            elif orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Error,
            ):
                self.exit_ticket = None

