            extendedMarketHours=False,
            dataNormalizationMode=DataNormalizationMode.Raw
        ).Symbol

        self.spy_option = self.AddOption("SPY", Resolution.Minute)
        self.option_symbol = self.spy_option.Symbol
        self.spy_option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )

        self.closes = []
        self.bucket_start = None
        self.bucket_bars = {}

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_symbol = None
        self.entry_price = None
        self.blocked_entry_date = None

    def OnData(self, slice):
        now = self.Time
        today = now.date()

        self._process_expiration_safety(now)
        self._process_exits(now, slice)

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        self._process_minute_bar(minute_bar, slice)

    def _process_minute_bar(self, bar, slice):
        bar_start = bar.EndTime - timedelta(minutes=1)
        if bar_start.tzinfo is None:
            bar_start = bar_start.replace(tzinfo=self.Time.tzinfo)

        if bar_start.time() < time(9, 30) or bar_start.time() >= time(16, 0):
            return

        bucket_start = bar_start.replace(
            minute=(bar_start.minute // 5) * 5,
            second=0,
            microsecond=0
        )

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self.bucket_start = bucket_start
            self.bucket_bars = {}

        if self.bucket_start is None:
            self.bucket_start = bucket_start

        if bar_start not in self.bucket_bars:
            self.bucket_bars[bar_start] = bar

        expected = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if len(self.bucket_bars) != 5:
            return

        if any(timestamp not in self.bucket_bars for timestamp in expected):
            self.bucket_bars = {}
            return

        completed_bar = TradeBar(
            self.bucket_start,
            self.spy,
            self.bucket_bars[expected[0]].Open,
            max(self.bucket_bars[t].High for t in expected),
            min(self.bucket_bars[t].Low for t in expected),
            self.bucket_bars[expected[-1]].Close,
            sum(self.bucket_bars[t].Volume for t in expected),
            timedelta(minutes=5)
        )

        self.bucket_bars = {}
        self._process_five_minute_bar(completed_bar, slice)

    def _process_five_minute_bar(self, bar, slice):
        if len(self.closes) >= 20:
            previous_fast = sum(self.closes[-5:]) / 5.0
            previous_slow = sum(self.closes[-20:]) / 20.0
        else:
            previous_fast = None
            previous_slow = None

        self.closes.append(float(bar.Close))
        if len(self.closes) > 20:
            self.closes.pop(0)

        if len(self.closes) < 20:
            return

        current_fast = sum(self.closes[-5:]) / 5.0
        current_slow = sum(self.closes[-20:]) / 20.0

        crossover = (
            previous_fast is not None and
            previous_slow is not None and
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        end_time = bar.EndTime
        eligible_time = time(9, 45) <= end_time.time() <= time(14, 30)

        if not crossover or not eligible_time:
            return

        if self.blocked_entry_date == self.Time.date():
            return

        if self._has_option_position() or self._entry_order_open():
            return

        self._try_enter(slice, bar.Close)

    def _try_enter(self, slice, spy_price):
        if self.option_symbol not in slice.OptionChains:
            self.Debug("Skipped entry: no option chain.")
            return

        chain = slice.OptionChains[self.option_symbol]
        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * float(spy_price)

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and float(contract.Strike) >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda contract: (float(contract.Strike), str(contract.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish 5-minute crossover entry"
        )
        self.held_symbol = selected.Symbol
        self.entry_price = None

    def _process_exits(self, now, slice):
        if not self._has_option_position() or self.held_symbol is None:
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()

        if now.date() >= expiry:
            self.blocked_entry_date = now.date()
            self._submit_exit("Expiration safety liquidation")
            return

        if (
            self._is_trading_day_before_expiry(now.date(), expiry)
            and now.time() >= time(15, 45)
        ):
            self._submit_exit("Pre-expiration time stop")
            return

        if self.entry_price is None or self.exit_ticket is not None:
            return

        if self.option_symbol not in slice.OptionChains:
            return

        chain = slice.OptionChains[self.option_symbol]
        contract = chain.Contracts.get(self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason):
        if self.exit_ticket is not None:
            status = self.exit_ticket.Status
            if status in (OrderStatus.New, OrderStatus.Submitted, OrderStatus.PartiallyFilled):
                return

        if self.held_symbol is None:
            return

        quantity = int(self.Portfolio[self.held_symbol].Quantity)
        if quantity <= 0:
            return

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Exit submitted: " + reason)

    def _process_expiration_safety(self, now):
        if self.held_symbol is None or not self._has_option_position():
            return

        expiry = self.Securities[self.held_symbol].Symbol.ID.Date.date()
        if now.date() >= expiry:
            self.blocked_entry_date = now.date()

    def _is_trading_day_before_expiry(self, current_date, expiry_date):
        if current_date >= expiry_date:
            return False

        candidate = expiry_date - timedelta(days=1)
        while candidate.weekday() >= 5:
            candidate -= timedelta(days=1)

        return current_date == candidate

    def _has_option_position(self):
        return (
            self.held_symbol is not None and
            self.Portfolio[self.held_symbol].Quantity > 0
        )

    def _entry_order_open(self):
        if self.entry_ticket is None:
            return False

        return self.entry_ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def OnOrderEvent(self, order_event):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = float(order_event.FillPrice)
                self.Debug(
                    "Call entry filled: {0} at {1}".format(
                        self.held_symbol,
                        self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.NoneStatus
            ):
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Option position liquidated.")
                self.exit_ticket = None
                self.entry_ticket = None
                self.held_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

    def OnAssignmentOrderEvent(self, assignment_event):
        self.Debug("Unexpected option exercise or assignment received.")

