        self.option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 365)
        )

        self.fast = SimpleMovingAverage(5)
        self.slow = SimpleMovingAverage(20)

        self._bucket_start = None
        self._bucket_bars = {}

        self._entry_ticket = None
        self._exit_ticket = None
        self._held_symbol = None
        self._entry_price = None
        self._expiration_date = None
        self._no_entries_today = False
        self._last_expiration_processing_date = None

    def OnData(self, slice: Slice):
        local_time = self.Time
        current_date = local_time.date()

        if current_date != self._last_expiration_processing_date:
            self._no_entries_today = False
            self._last_expiration_processing_date = current_date

        self._process_expiration(current_date)

        if self._held_symbol is not None:
            self._evaluate_exit(slice)

        if self.spy not in slice.Bars:
            return

        minute_bar = slice.Bars[self.spy]
        minute_time = local_time.replace(second=0, microsecond=0)

        if minute_time.time() < time(9, 30) or minute_time.time() >= time(16, 0):
            return

        bucket_start = minute_time.replace(
            minute=(minute_time.minute // 5) * 5
        )

        if self._bucket_start is None:
            self._bucket_start = bucket_start

        if bucket_start != self._bucket_start:
            self._finalize_bucket(slice)
            self._bucket_bars = {}
            self._bucket_start = bucket_start

        self._bucket_bars[minute_time] = minute_bar

    def _finalize_bucket(self, slice: Slice):
        if self._bucket_start is None:
            return

        expected_times = [
            self._bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if any(t not in self._bucket_bars for t in expected_times):
            return

        closes = [self._bucket_bars[t].Close for t in expected_times]
        close = closes[-1]
        end_time = self._bucket_start + timedelta(minutes=5)

        prior_ready = self.fast.IsReady and self.slow.IsReady
        prior_fast = self.fast.Current.Value if prior_ready else None
        prior_slow = self.slow.Current.Value if prior_ready else None

        self.fast.Update(end_time, close)
        self.slow.Update(end_time, close)

        if not (self.fast.IsReady and self.slow.IsReady):
            return

        current_fast = self.fast.Current.Value
        current_slow = self.slow.Current.Value

        bullish_cross = (
            prior_ready
            and prior_fast <= prior_slow
            and current_fast > current_slow
        )

        end_clock = end_time.time()
        eligible_time = time(9, 45) <= end_clock <= time(14, 30)

        if bullish_cross and eligible_time:
            self._evaluate_entry(slice)

    def _evaluate_entry(self, slice: Slice):
        if self._no_entries_today:
            return

        if self._held_symbol is not None or self._entry_order_open():
            return

        chains = list(slice.OptionChains.Values)
        if not chains:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        candidates_by_expiration = {}

        for chain in chains:
            for contract in chain.Contracts.Values:
                symbol = contract.Symbol
                if symbol.ID.OptionRight != OptionRight.Call:
                    continue

                expiration = symbol.ID.Date.date()
                if expiration < minimum_expiration:
                    continue

                candidates_by_expiration.setdefault(expiration, []).append(contract)

        if not candidates_by_expiration:
