    def OnData(self, slice: Slice):
        current_date = self.Time.date()

        self._process_expiration_state(current_date)
        self._process_minute_exit(slice)

        if self.entry_symbol is not None or self._entry_order_is_open():
            self._process_spy_minute_bar(slice)
            return

        self._process_spy_minute_bar(slice, allow_entry=True)

    def _process_spy_minute_bar(self, slice: Slice, allow_entry=False):
        if not slice.Bars.ContainsKey(self.spy.Symbol):
            return

        bar = slice.Bars[self.spy.Symbol]
        bar_time = bar.Time

        if bar_time.time() < time(9, 30) or bar_time.time() >= time(16, 0):
            self._finalize_bucket_if_needed(allow_entry=False)
            return

        minutes_from_open = (bar_time.hour * 60 + bar_time.minute) - (9 * 60 + 30)
        bucket_minute = (minutes_from_open // 5) * 5
        bucket_start = datetime(
            bar_time.year,
            bar_time.month,
            bar_time.day,
            9,
            30
        ) + timedelta(minutes=bucket_minute)

        if self.bucket_start is not None and bucket_start != self.bucket_start:
            self._finalize_bucket_if_needed(allow_entry)
            self.bucket_bars = {}

        if self.bucket_start is None or bucket_start != self.bucket_start:
            self.bucket_start = bucket_start

        self.bucket_bars[bar_time] = bar

    def _finalize_bucket_if_needed(self, allow_entry):
        if self.bucket_start is None:
            return

        expected_times = [
            self.bucket_start + timedelta(minutes=i)
            for i in range(5)
        ]

        if not all(t in self.bucket_bars for t in expected_times):
            self.bucket_start = None
            self.bucket_bars = {}
            return

        bars = [self.bucket_bars[t] for t in expected_times]
        consolidated = TradeBar(
            self.bucket_start,
            self.spy.Symbol,
            bars[0].Open,
            max(b.High for b in bars),
            min(b.Low for b in bars),
            bars[-1].Close,
            sum(b.Volume for b in bars),
            timedelta(minutes=5)
        )

        self._update_averages_and_check_signal(consolidated, allow_entry)

        self.bucket_start = None
        self.bucket_bars = {}

    def _update_averages_and_check_signal(self, bar, allow_entry):
        previous_fast = self.fast.Current.Value if self.fast.IsReady else None
        previous_slow = self.slow.Current.Value if self.slow.IsReady else None
        previous_ready = self.fast.IsReady and self.slow.IsReady

        self.fast.Update(bar.EndTime, bar.Close)
        self.slow.Update(bar.EndTime, bar.Close)

        if not allow_entry or self.expiration_block_date == self.Time.date():
            return

        bar_end_time = bar.EndTime.time()
        if bar_end_time < time(9, 45) or bar_end_time > time(14, 30):
            return

        if not previous_ready or not self.fast.IsReady or not self.slow.IsReady:
            return

        bullish_cross = (
            previous_fast <= previous_slow
            and self.fast.Current.Value > self.slow.Current.Value
        )

        if bullish_cross:
            self._attempt_entry()

    def _attempt_entry(self):
        if self.entry_symbol is not None or self._entry_order_is_open():
            return

        chain = None
        for candidate in self.CurrentSlice.OptionChains.Values:
            if candidate.Symbol == self.spy_option.Symbol:
                chain = candidate
                break

        if chain is None:
            self.Debug("Skipped entry: no SPY option chain in current Slice.")
            return

        algorithm_date = self.Time.date()
        minimum_expiry = algorithm_date + timedelta(days=7)

        contracts = list(chain.Contracts.Values)
        eligible_expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not eligible_expirations:
            self.Debug("Skipped entry: no expiration at least 7 calendar days away.")
            return

        selected_expiry = eligible_expirations[0]
        spy_price = self.Securities[self.spy.Symbol].Price
        minimum_strike = spy_price * 1.01

        eligible_contracts = [
            contract
            for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not eligible_contracts:
            self.Debug("Skipped entry: no qualifying call at selected expiration.")
            return

        selected_contract = sorted(
            eligible_contracts,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )[0]

        self.entry_symbol = selected_contract.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(self.entry_symbol, 1)
        self.Debug(f"Entry submitted: {self.entry_symbol}")

    def _process_minute_exit(self, slice: Slice):
        if self.entry_symbol is None or self.entry_price is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        security = self.Securities[self.entry_symbol]
        if not security.Invested:
            return

        contract = None
        for chain in slice.OptionChains.Values:
            if chain.Contracts.ContainsKey(self.entry_symbol):
                contract = chain.Contracts[self.entry_symbol]
                break

        current_date = self.Time.date()
        expiry_date = self.entry_symbol.ID.Date.date()

        if current_date == expiry_date - timedelta(days=1):
            if self.Time.time() >= time(15, 45):
                self._submit_exit("expiration-eve time stop")
                return

        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid > 0 and ask > 0:
            midpoint = (bid + ask) / 2.0
            if midpoint >= 1.50 * self.entry_price:
                self._submit_exit("50% profit target")

    def _process_expiration_state(self, current_date):
        if self.entry_symbol is None:
            return

        expiry_date = self.entry_symbol.ID.Date.date()
        if current_date >= expiry_date:
            self.expiration_block_date = current_date

            if self.Securities[self.entry_symbol].Invested:
                self._submit_exit("expiration processing")

    def _submit_exit(self, reason):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            return

        if not self.Securities[self.entry_symbol].Invested:
            return

        if self.exit_ticket is not None:
            self.Transactions.CancelOrder(self.exit_ticket.OrderId)

        quantity = -self.Securities[self.entry_symbol].Holdings.Quantity
        if quantity != 0:
            self.exit_ticket = self.MarketOrder(self.entry_symbol, quantity)
            self.Debug(f"Exit submitted ({reason}): {self.entry_symbol}")

    def OnOrderEvent(self, order_event: OrderEvent):
        if self.entry_ticket is not None and order_event.OrderId == self.entry_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    f"Entry filled: {self.entry_symbol}, "
                    f"price={self.entry_price}"
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None_,
            ):
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None

        if self.exit_ticket is not None and order_event.OrderId == self.exit_ticket.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.entry_symbol}")
                self.entry_ticket = None
                self.entry_symbol = None
                self.entry_price = None
                self.exit_ticket = None
            elif order_event.Status in (OrderStatus.Canceled, OrderStatus.Invalid):
                self.exit_ticket = None

        if order_event.OrderType == OrderType.OptionExercise:
            self.Debug(f"Unexpected option exercise handling: {order_event}")

    def OnAssignmentOrderEvent(self, assignment_event: AssignmentOrderEvent):
        self.Debug(f"Unexpected option assignment handling: {assignment_event}")

    def _entry_order_is_open(self):
        return self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket)

    def _ticket_is_open(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
        )

