        self.option.SetFilter(
            lambda u: u.IncludeWeeklys()
            .Strikes(-200, 200)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.closes = deque(maxlen=20)
        self.current_bucket = None
        self.bucket_bars = []
        self.previous_fast = None
        self.previous_slow = None

        self.held_symbol = None
        self.entry_order_id = None
        self.entry_price = None
        self.exit_order_id = None
        self.no_entry_date = None

    def OnData(self, data: Slice):
        today = self.Time.date()

        # Never intentionally hold through expiration.
        if self.held_symbol is not None:
            expiry = self._expiry_date(self.held_symbol)
            if expiry is not None and today >= expiry:
                self.no_entry_date = today
                self._submit_exit("expiration processing")
                return

        if self.held_symbol is not None and self.entry_price is not None:
            self._evaluate_open_position(data)

        spy_bar = None
        if data.Bars.ContainsKey(self.spy):
            spy_bar = data.Bars[self.spy]

        if spy_bar is None:
            return

        bar_end = spy_bar.EndTime
        if bar_end.tzinfo is not None:
            local_end = bar_end.astimezone().replace(tzinfo=None)
        else:
            local_end = bar_end

        if local_end.date() != today:
            return

        minute_start = local_end - timedelta(minutes=1)
        if not (
            minute_start.hour > 9
            or (minute_start.hour == 9 and minute_start.minute >= 30)
        ):
            return
        if minute_start.hour >= 16:
            return

        bucket_start = minute_start.replace(
            minute=(minute_start.minute // 5) * 5,
            second=0,
            microsecond=0,
        )
        bucket_end = bucket_start + timedelta(minutes=5)

        if self.current_bucket != bucket_start:
            self.current_bucket = bucket_start
            self.bucket_bars = []

        expected_start = bucket_start + timedelta(minutes=len(self.bucket_bars))
        if minute_start != expected_start:
            self.bucket_bars = []
            return

        self.bucket_bars.append(spy_bar)

        if local_end.minute % 5 != 0 or len(self.bucket_bars) != 5:
            return

        consolidated_close = self.bucket_bars[-1].Close
        self.bucket_bars = []

        prior_fast = self.previous_fast
        prior_slow = self.previous_slow

        self.closes.append(consolidated_close)
        if len(self.closes) >= 5:
            current_fast = sum(list(self.closes)[-5:]) / 5.0
        else:
            current_fast = None

        if len(self.closes) >= 20:
            current_slow = sum(self.closes) / 20.0
        else:
            current_slow = None

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if (
            bucket_end.time() < datetime.time(9, 45)
            or bucket_end.time() > datetime.time(14, 30)
            or prior_fast is None
            or prior_slow is None
            or current_fast is None
            or current_slow is None
            or self.entry_order_id is not None
            or self.held_symbol is not None
            or self.no_entry_date == today
        ):
            return

        if prior_fast <= prior_slow and current_fast > current_slow:
            self._try_enter(data, consolidated_close)

    def _try_enter(self, data: Slice, spy_price: float):
        if not data.OptionChains:
            self.Debug("Skipped entry: current Slice has no option chain.")
            return

        today = self.Time.date()
        minimum_expiry = today + timedelta(days=7)
        candidates = []

        for chain in data.OptionChains.Values:
            for contract in chain:
                expiry = self._expiry_date(contract.Symbol)
                if (
                    expiry is not None
                    and expiry >= minimum_expiry
                    and contract.Right == OptionRight.Call
                ):
                    candidates.append(contract)

        if not candidates:
            self.Debug("Skipped entry: no qualifying option expiration.")
            return

        selected_expiry = min(self._expiry_date(c.Symbol) for c in candidates)
        strike_floor = 1.01 * spy_price

        strike_candidates = [
            c for c in candidates
            if self._expiry_date(c.Symbol) == selected_expiry
            and c.Strike >= strike_floor
        ]

        if not strike_candidates:
            self.Debug("Skipped entry: no qualifying call strike.")
            return

        selected = min(
            strike_candidates,
            key=lambda c: (c.Strike, str(c.Symbol))
        )

        self.held_symbol = selected.Symbol
        self.entry_order_id = None
        self.entry_price = None

        ticket = self.MarketOrder(selected.Symbol, 1)
        self.entry_order_id = ticket.OrderId
        self.Debug("Entry submitted: {}".format(selected.Symbol))

    def _evaluate_open_position(self, data: Slice):
        if self.held_symbol is None:
            return

        expiry = self._expiry_date(self.held_symbol)
        if expiry is not None and self._is_pre_expiration_stop_time(expiry):
            self._submit_exit("pre-expiration time stop")
            return

        if self.exit_order_id is not None:
            return

        quote = self._get_current_contract(data, self.held_symbol)
        if quote is None:
            return

        bid = quote.BidPrice
        ask = quote.AskPrice
        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._cancel_exit_orders()
            self._submit_exit("50% profit target")

    def _submit_exit(self, reason: str):
        if self.held_symbol is None or self.exit_order_id is not None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        ticket = self.MarketOrder(self.held_symbol, -quantity)
        self.exit_order_id = ticket.OrderId
        self.Debug("Exit submitted ({}): {}".format(reason, self.held_symbol))

    def _cancel_exit_orders(self):
        if self.exit_order_id is not None:
            ticket = self.Transactions.GetOrderTicket(self.exit_order_id)
            if ticket is not None and ticket.Status not in (
                OrderStatus.Filled,
                OrderStatus.Canceled,
                OrderStatus.Invalid,
            ):
                ticket.Cancel("Profit target supersedes existing exit")

    def _get_current_contract(self, data: Slice, symbol: Symbol):
        if not data.OptionChains:
            return None

        for chain in data.OptionChains.Values:
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _expiry_date(self, symbol: Symbol):
        try:
            return symbol.ID.Date.date()
        except Exception:
            return None

    def _is_pre_expiration_stop_time(self, expiry):
        today = self.Time.date()
        if today >= expiry:
            return False

        # Confirm that today is the last open trading day before expiry.
        date = today + timedelta(days=1)
        while date < expiry:
            if self.Securities[self.spy].Exchange.Hours.IsDateOpen(date):
                return False
            date += timedelta(days=1)

        return self.Time.hour == 15 and self.Time.minute >= 45

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_order_id is not None
            and order_event.OrderId == self.entry_order_id
        ):
            if order_event.Status in (
                OrderStatus.PartiallyFilled,
                OrderStatus.Filled,
            ):
                if order_event.FillQuantity > 0:
                    self.entry_price = order_event.FillPrice

                if order_event.Status == OrderStatus.Filled:
                    self.Debug(
                        "Entry filled: {} at {}".format(
                            self.held_symbol, self.entry_price
                        )
                    )
                    self.entry_order_id = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.Debug("Entry order did not fill: {}".format(order_event.Status))
                self.entry_order_id = None
                self.held_symbol = None
                self.entry_price = None

        if (
            self.exit_order_id is not None
            and order_event.OrderId == self.exit_order_id
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {}".format(self.held_symbol))
                self.exit_order_id = None
                self.held_symbol = None
                self.entry_price = None

            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Rejected,
            ):
                self.exit_order_id = None

    def OnAssignmentOrderEvent(self, assignment_event: OrderEvent):
        self.Debug(
            "Unexpected option exercise or assignment: {}".format(
                assignment_event.Symbol
            )
        )

