        self.exit_ticket = None
        self.expiration_block_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        self.current_slice_chain = None
        self.current_slice_has_chain = False

        try:
            if slice.OptionChains.ContainsKey(self.option_symbol):
                self.current_slice_chain = list(slice.OptionChains[self.option_symbol])
                self.current_slice_has_chain = True
        except Exception:
            self.current_slice_chain = None
            self.current_slice_has_chain = False

        if slice.Bars.ContainsKey(self.spy):
            self.latest_spy_price = slice.Bars[self.spy].Close

        self.ProcessExpiration()
        self.ProcessExitChecks(slice)

        if slice.Bars.ContainsKey(self.spy):
            bar = slice.Bars[self.spy]
            bar_time = bar.End.time()

            if time(9, 30) <= bar.Time.time() < time(16, 0):
                self.consolidator.Update(bar)

    def OnFiveMinuteBar(self, sender, bar: TradeBar):
        bar_end = bar.End
        end_time = bar_end.time()

        if not (time(9, 30) < end_time <= time(16, 0)):
            return

        self.closes.Add(float(bar.Close))

        if not self.closes.IsReady:
            return

        current_fast = sum(
            self.closes[i] for i in range(self.fast_period)
        ) / self.fast_period

        current_slow = sum(
            self.closes[i] for i in range(self.slow_period)
        ) / self.slow_period

        bullish_crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        self.previous_fast = current_fast
        self.previous_slow = current_slow

        if not bullish_crossover:
            return

        if not (time(9, 45) <= end_time <= time(14, 30)):
            return

        self.TryEnterCall()

    def TryEnterCall(self):
        today = self.Time.date()

        if self.expiration_block_date == today:
            return

        if self.held_symbol is not None:
            return

        if self.IsEntryOrderOpen():
            return

        if not self.current_slice_has_chain or self.current_slice_chain is None:
            self.Debug("Skipped call selection: no option chain.")
            return

        if self.latest_spy_price is None or self.latest_spy_price <= 0:
            self.Debug("Skipped call selection: invalid SPY price.")
            return

        eligible = []
        for contract in self.current_slice_chain:
            expiry = self.ToDate(contract.Expiry)
            if expiry >= today + timedelta(days=7):
                eligible.append((expiry, contract))

        if not eligible:
            self.Debug("Skipped call selection: no expiration at least 7 days out.")
            return

        nearest_expiry = min(item[0] for item in eligible)
        threshold = 1.01 * self.latest_spy_price

        candidates = [
            contract for expiry, contract in eligible
            if expiry == nearest_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= threshold
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)
        self.Debug(
            "Call entry submitted: {0}, expiry {1}, strike {2}".format(
                selected.Symbol, nearest_expiry, selected.Strike
            )
        )

    def ProcessExitChecks(self, slice: Slice):
        if self.held_symbol is None or self.entry_price is None:
            return

        holding = self.Portfolio[self.held_symbol]
        if not holding.Invested:
            return

        expiry = self.ToDate(self.Securities[self.held_symbol].Symbol.ID.Date)
        today = self.Time.date()

        if today >= expiry:
            self.expiration_block_date = today
            self.SubmitExit("expiration processing")
            return

        previous_trading_day = self.PreviousTradingDay(expiry)
        if (
            today == previous_trading_day
            and self.Time.time() >= time(15, 45)
        ):
            self.SubmitExit("pre-expiration time stop")
            return

        if not slice.QuoteBars.ContainsKey(self.held_symbol):
            return

        quote = slice.QuoteBars[self.held_symbol]
        bid = quote.Bid.Close
        ask = quote.Ask.Close

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self.SubmitExit("50 percent profit target")

    def ProcessExpiration(self):
        if self.held_symbol is None:
            return

        expiry = self.ToDate(self.Securities[self.held_symbol].Symbol.ID.Date)
        if self.Time.date() >= expiry:
            self.expiration_block_date = self.Time.date()
            self.SubmitExit("expiration processing")

    def SubmitExit(self, reason):
        if self.held_symbol is None:
            return

        holding = self.Portfolio[self.held_symbol]
        quantity = holding.Quantity

        if quantity == 0:
            return

        if self.exit_ticket is not None and self.IsOrderOpen(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity,
            tag=reason
        )
        self.Debug("Option exit submitted: {0}".format(reason))

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(order_event.Message).lower()
        if (
            getattr(order_event, "IsAssignment", False)
            or "assignment" in message
            or "exercise" in message
        ):
            self.Debug("Unexpected option exercise or assignment: {0}".format(
                order_event.Message
            ))
            self.expiration_block_date = self.Time.date()

        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.held_symbol = order_event.Symbol
            self.entry_price = float(order_event.FillPrice)
            self.Debug(
                "Call entry filled: {0} at {1}".format(
                    self.held_symbol, self.entry_price
                )
            )

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
            and order_event.Status == OrderStatus.Filled
        ):
            self.Debug("Call exit filled: {0}".format(order_event.Symbol))
            self.held_symbol = None
            self.entry_price = None
            self.exit_ticket = None
            self.entry_ticket = None

    def IsEntryOrderOpen(self):
        return self.entry_ticket is not None and self.IsOrderOpen(self.entry_ticket)

    def IsOrderOpen(self, ticket):
        return ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled,
            OrderStatus.CancelPending
        )

    def PreviousTradingDay(self, date_value):
        candidate = date_value - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(
            datetime(candidate.year, candidate.month, candidate.day)
        ):
            candidate -= timedelta(days=1)
        return candidate

    @staticmethod
    def ToDate(value):
        if hasattr(value, "date"):
            return value.date()
        return value

