from AlgorithmImports import *
from collections import OrderedDict
from datetime import datetime, timedelta


class SpyFiveMinuteCallCrossover(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone(TimeZones.NewYork)

        equity = self.AddEquity("SPY", Resolution.Minute)
        equity.SetDataNormalizationMode(DataNormalizationMode.Raw)
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        option.SetFilter(
            lambda universe: universe
                .IncludeWeeklys()
                .Strikes(-200, 200)
                .Expiration(0, 730)
        )
        self.option_symbol = option.Symbol

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []
        self.previous_fast = None
        self.previous_slow = None

        self.bucket_end = None
        self.bucket_closes = {}

        self.entry_ticket = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_triggered = False
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            expiration = self.entry_symbol.ID.Date.date()
            if today >= expiration:
                self.blocked_entry_date = today
                self._submit_exit("expiration processing")

        self._evaluate_open_position(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        local_time = end_time.time()

        if local_time <= datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = end_time.minute
        bucket_end = end_time.replace(
            minute=minute + (5 - minute % 5) if minute % 5 else minute
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.bucket_closes = {}

        self.bucket_end = bucket_end
        self.bucket_closes[end_time] = bar.Close

        if minute % 5 != 0:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.bucket_closes for t in expected):
            self.bucket_closes = {}
            return

        consolidated_close = self.bucket_closes[bucket_end]
        self.bucket_closes = {}

        self._process_five_minute_close(consolidated_close, bucket_end, slice)

    def _process_five_minute_close(self, close, end_time, slice: Slice):
        if len(self.closes) >= self.slow_period:
            self.previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            self.previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        if crossover and eligible_time:
            self._try_enter(slice)

    def _try_enter(self, slice: Slice):
        today = self.Time.date()

        if self.blocked_entry_date == today:
            return

        if self.entry_ticket is not None:
            status = self.entry_ticket.Status
            if status not in [
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ]:
                return

        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            return

        if self.spy not in slice.Bars:
            self.Debug("Skipped call selection: no current SPY price.")
            return

        chains = self._get_option_chains(slice)
        if not chains:
            self.Debug("Skipped call selection: no option chain in current Slice.")
            return

        current_date = today
        minimum_expiration = current_date + timedelta(days=7)
        current_price = slice.Bars[self.spy].Close

        contracts = []
        for chain in chains:
            for contract in chain:
                if contract.Right != OptionRight.Call:
                    continue
                expiration_date = contract.Expiry.date()
                if expiration_date >= minimum_expiration:
                    contracts.append(contract)

        if not contracts:
            self.Debug("Skipped call selection: no expiration satisfies the rule.")
            return

        nearest_expiration = min(c.Expiry.date() for c in contracts)
        strike_floor = current_price * 1.01

        candidates = [
            c for c in contracts
            if c.Expiry.date() == nearest_expiration
            and c.Strike >= strike_floor
        ]

        if not candidates:
            self.Debug("Skipped call selection: no qualifying call strike.")
            return

        selected = min(
            candidates,
            key=lambda c: (c.Strike, str(c.Symbol.Value))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="Bullish five-minute crossover entry"
        )

    def _evaluate_open_position(self, slice: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        expiration_date = self.entry_symbol.ID.Date.date()
        today = self.Time.date()

        # Time stop at 15:45 on the trading day immediately before expiration.
        previous_trading_day = self._previous_trading_day(expiration_date)
        if (
