        quantity = -holding.Quantity
        self.exit_triggered = True
        self.exit_ticket = self.MarketOrder(
            self.entry_symbol,
            quantity,
            tag=reason
        )
        self.Debug("Exit submitted for {}: {}".format(self.entry_symbol, reason))

    def _get_option_chains(self, slice: Slice):
        result = []
        try:
            chain = slice.OptionChains[self.option_symbol]
