        self.exit_ticket = None
        self.exit_triggered = False
        self.blocked_entry_date = None

    def OnData(self, slice: Slice):
        today = self.Time.date()

        # Never intentionally carry an option into its expiration date.
        if self.entry_symbol is not None and self.Portfolio[self.entry_symbol].Invested:
            expiration = self.entry_symbol.ID.Date.date()
            if today >= expiration:
                self.blocked_entry_date = today
                self._submit_exit("expiration processing")

        self._evaluate_open_position(slice)

        if self.spy not in slice.Bars:
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime.replace(second=0, microsecond=0)
        local_time = end_time.time()

        if local_time <= datetime.strptime("09:30", "%H:%M").time():
            return
        if local_time > datetime.strptime("16:00", "%H:%M").time():
            return

        minute = end_time.minute
        bucket_end = end_time.replace(
            minute=minute + (5 - minute % 5) if minute % 5 else minute
        )

        if self.bucket_end is not None and bucket_end != self.bucket_end:
            self.bucket_closes = {}

        self.bucket_end = bucket_end
        self.bucket_closes[end_time] = bar.Close

        if minute % 5 != 0:
            return

        expected = [
            bucket_end - timedelta(minutes=i)
            for i in range(4, -1, -1)
        ]

        if not all(t in self.bucket_closes for t in expected):
            self.bucket_closes = {}
            return

        consolidated_close = self.bucket_closes[bucket_end]
        self.bucket_closes = {}

        self._process_five_minute_close(consolidated_close, bucket_end, slice)

    def _process_five_minute_close(self, close, end_time, slice: Slice):
        if len(self.closes) >= self.slow_period:
            self.previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            self.previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(close)
        if len(self.closes) > self.slow_period:
            self.closes.pop(0)

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        crossover = (
            self.previous_fast is not None
            and self.previous_slow is not None
            and self.previous_fast <= self.previous_slow
            and current_fast > current_slow
        )

        eligible_time = (
            end_time.hour > 9 or
            (end_time.hour == 9 and end_time.minute >= 45)
        ) and (
            end_time.hour < 14 or
            (end_time.hour == 14 and end_time.minute <= 30)
        )

        if crossover and eligible_time:
            self._try_enter(slice)

