from AlgorithmImports import *
from datetime import datetime, timedelta, time


class SpyCallCrossoverAlgorithm(QCAlgorithm):

    def Initialize(self):
        self.SetStartDate(2023, 4, 1)
        self.SetEndDate(2026, 6, 30)
        self.SetCash(100000)
        self.SetTimeZone("America/New_York")

        equity = self.AddEquity(
            "SPY",
            Resolution.Minute,
            dataNormalizationMode=DataNormalizationMode.Raw
        )
        self.spy = equity.Symbol

        option = self.AddOption("SPY", Resolution.Minute)
        self.option = option
        option.SetFilter(
            lambda universe: universe
            .Strikes(-100, 100)
            .Expiration(timedelta(days=0), timedelta(days=365))
        )

        self.fast_period = 5
        self.slow_period = 20
        self.closes = []

        self.minute_bars = {}
        self.current_chain = None

        self.entry_ticket = None
        self.exit_ticket = None
        self.held_contract = None
        self.entry_price = None
        self.expiration_blocked_date = None

    def OnData(self, slice: Slice):
        self.current_chain = None
        if slice.OptionChains.ContainsKey(self.option.Symbol):
            self.current_chain = slice.OptionChains[self.option.Symbol]

        self._process_expiration_and_time_stop()

        if not slice.Bars.ContainsKey(self.spy):
            return

        bar = slice.Bars[self.spy]
        self._process_minute_bar(bar, slice)

    def _process_minute_bar(self, bar: TradeBar, slice: Slice):
        end_time = bar.EndTime
        local_end = end_time

        if local_end.time() < time(9, 31) or local_end.time() > time(16, 0):
            return

        minute = local_end.replace(second=0, microsecond=0)

        if minute.minute % 5 == 0:
            bucket_start = minute - timedelta(minutes=4)
            bucket = self.minute_bars.pop(bucket_start, None)

            if bucket is not None and len(bucket) == 5:
                consolidated = self._consolidate(bucket, local_end)
                self._process_five_minute_bar(consolidated, slice)

        bucket_start = minute - timedelta(minutes=(minute.minute - 1) % 5)
        if bucket_start.time() >= time(9, 31) and bucket_start.time() <= time(15, 56):
            self.minute_bars.setdefault(bucket_start, {})[minute] = bar

    def _consolidate(self, bars, end_time):
        ordered = [bars[key] for key in sorted(bars)]
        return TradeBar(
            end_time - timedelta(minutes=5),
            self.spy,
            ordered[0].Open,
            max(x.High for x in ordered),
            min(x.Low for x in ordered),
            ordered[-1].Close,
            sum(x.Volume for x in ordered),
            timedelta(minutes=5)
        )

    def _process_five_minute_bar(self, bar: TradeBar, slice: Slice):
        previous_fast = None
        previous_slow = None

        if len(self.closes) >= self.slow_period:
            previous_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
            previous_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        self.closes.append(float(bar.Close))

        if len(self.closes) < self.slow_period:
            return

        current_fast = sum(self.closes[-self.fast_period:]) / self.fast_period
        current_slow = sum(self.closes[-self.slow_period:]) / self.slow_period

        if previous_fast is None or previous_slow is None:
            return

        crossover = (
            previous_fast <= previous_slow and
            current_fast > current_slow
        )

        bar_end = bar.EndTime.time()
        eligible_time = time(9, 45) <= bar_end <= time(14, 30)

        if crossover and eligible_time:
            self._try_entry(slice, float(bar.Close))

    def _try_entry(self, slice: Slice, spy_price: float):
        if self.expiration_blocked_date == self.Time.date():
            return

        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        if self.held_contract is not None:
            if self.Portfolio[self.held_contract].Quantity != 0:
                return

        if self.current_chain is None:
            self.Debug("Skipped entry: no option chain.")
            return

        current_date = self.Time.date()
        minimum_expiration = current_date + timedelta(days=7)

        contracts = list(self.current_chain.Contracts.Values)
        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiration
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days out.")
            return

        selected_expiration = expirations[0]
        minimum_strike = spy_price * 1.01

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiration
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        candidates.sort(key=lambda c: (float(c.Strike), str(c.Symbol)))
        selected = candidates[0]

        self.held_contract = selected.Symbol
        self.entry_price = None
        self.entry_ticket = self.MarketOrder(selected.Symbol, 1)

    def OnOrderEvent(self, orderEvent: OrderEvent):
        if self.entry_ticket is not None and orderEvent.OrderId == self.entry_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                if orderEvent.FillQuantity > 0:
                    self.entry_price = float(orderEvent.FillPrice)
                    self.Debug(
                        f"Entry filled: {self.held_contract} "
                        f"at {self.entry_price:.4f}"
                    )

            if orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                if orderEvent.Status != OrderStatus.Filled:
                    self.Debug("Entry order did not fill.")
                    if self.held_contract is not None and self.Portfolio[
                        self.held_contract
                    ].Quantity == 0:
                        self.held_contract = None
                        self.entry_price = None
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract}")
                self.held_contract = None
                self.entry_price = None

            if orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                self.exit_ticket = None

        if getattr(orderEvent, "IsAssignment", False):
            self.Debug("Unexpected option assignment received.")

    def OnAssignmentOrder(self, assignmentOrderEvent: AssignmentOrderEvent):
        self.Debug("Unexpected option exercise or assignment received.")

    def _process_expiration_and_time_stop(self):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        expiration_date = self.held_contract.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        if current_date >= expiration_date:
            self.expiration_blocked_date = current_date
            self._cancel_entry_order()
            self._submit_exit("expiration")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)

        if (
            current_date == previous_trading_day and
            current_time >= time(15, 45)
        ):
            self._submit_exit("time stop")

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if self.Portfolio[self.held_contract].Quantity == 0:
            return

        if not slice.OptionQuotes.ContainsKey(self.held_contract):
            return

        quote = slice.OptionQuotes[self.held_contract]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _cancel_entry_order(self):
        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation")

    def _ticket_done(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def OnEndOfDay(self, symbol):
        if symbol != self.spy:
            return

        self._evaluate_profit_target(self.CurrentSlice)

