                    ].Quantity == 0:
                        self.held_contract = None
                        self.entry_price = None
                self.entry_ticket = None

        if self.exit_ticket is not None and orderEvent.OrderId == self.exit_ticket.OrderId:
            if orderEvent.Status == OrderStatus.Filled:
                self.Debug(f"Exit filled: {self.held_contract}")
                self.held_contract = None
                self.entry_price = None

            if orderEvent.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.Filled
            ):
                self.exit_ticket = None

        if getattr(orderEvent, "IsAssignment", False):
            self.Debug("Unexpected option assignment received.")

    def OnAssignmentOrder(self, assignmentOrderEvent: AssignmentOrderEvent):
        self.Debug("Unexpected option exercise or assignment received.")

    def _process_expiration_and_time_stop(self):
        if self.held_contract is None:
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        expiration_date = self.held_contract.ID.Date.date()
        current_date = self.Time.date()
        current_time = self.Time.time()

        if current_date >= expiration_date:
            self.expiration_blocked_date = current_date
            self._cancel_entry_order()
            self._submit_exit("expiration")
            return

        previous_trading_day = self._previous_trading_day(expiration_date)

        if (
            current_date == previous_trading_day and
            current_time >= time(15, 45)
        ):
            self._submit_exit("time stop")

    def _evaluate_profit_target(self, slice: Slice):
        if self.held_contract is None or self.entry_price is None:
            return

        if self.Portfolio[self.held_contract].Quantity == 0:
            return

        if not slice.OptionQuotes.ContainsKey(self.held_contract):
            return

        quote = slice.OptionQuotes[self.held_contract]
        bid = float(quote.Bid.Close)
        ask = float(quote.Ask.Close)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("profit target")

    def _submit_exit(self, reason: str):
        if self.held_contract is None:
            return

        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            return

        quantity = self.Portfolio[self.held_contract].Quantity
        if quantity == 0:
            return

        self._cancel_open_exit_orders()
        self.exit_ticket = self.MarketOrder(
            self.held_contract,
            -quantity,
            tag=reason
        )
        self.Debug(f"Exit submitted: {reason}")

    def _cancel_entry_order(self):
        if self.entry_ticket is not None and not self._ticket_done(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")

    def _cancel_open_exit_orders(self):
        if self.exit_ticket is not None and not self._ticket_done(self.exit_ticket):
            self.exit_ticket.Cancel("Replaced by liquidation")

    def _ticket_done(self, ticket):
        return ticket.Status in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )

    def _previous_trading_day(self, date_value):
        date_value -= timedelta(days=1)
        exchange_hours = self.Securities[self.spy].Exchange.Hours

        while not exchange_hours.IsDateOpen(date_value):
            date_value -= timedelta(days=1)

        return date_value

    def OnEndOfDay(self, symbol):
        if symbol != self.spy:
            return

        self._evaluate_profit_target(self.CurrentSlice)

