            self.minute_bars = {}

        if self.aggregation_bucket is None or bucket != self.aggregation_bucket:
            self.aggregation_bucket = bucket
            self.aggregation_date = bar_date
            self.minute_bars = {}

        self.minute_bars[bar_time] = bar

    def _emit_consolidated_bar(self, slice: Slice):
        if self.aggregation_bucket is None:
            return

        bucket = self.aggregation_bucket
        expected_times = [
            bucket + timedelta(minutes=i) for i in range(5)
        ]

        if any(timestamp not in self.minute_bars for timestamp in expected_times):
            self.Debug(
                "Skipped incomplete five-minute SPY bar ending {}".format(
                    bucket + timedelta(minutes=5)
                )
            )
            return

        bars = [self.minute_bars[timestamp] for timestamp in expected_times]
        close = bars[-1].Close

        self.fast_values.append(float(close))
        self.slow_values.append(float(close))

