        if self.held_symbol is None or self.entry_price is None:
            return

        contract = self._find_contract(slice, self.held_symbol)
        if contract is None:
            return

        bid = float(contract.BidPrice)
        ask = float(contract.AskPrice)

        if bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint < 1.50 * self.entry_price:
            return

        self._submit_exit("profit target")

    def _evaluate_time_stop(self):
        if self.held_symbol is None:
            return

        security = self.Securities.get(self.held_symbol)
        if security is None:
            return

        expiry_date = security.Symbol.ID.Date.date()
        stop_date = self._previous_trading_day(expiry_date)

        if self.Time.date() == stop_date and self.Time.hour == 15 and self.Time.minute == 45:
            self._submit_exit("expiration time stop")

    def _process_expiration(self, current_date):
        if self.held_symbol is not None:
            security = self.Securities.get(self.held_symbol)
            if security is not None:
                expiry_date = security.Symbol.ID.Date.date()
                if current_date >= expiry_date:
                    self.expiration_block_date = current_date
                    self._cancel_entry_if_open()
                    self._submit_exit("expiration processing")

        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            if self.entry_symbol is not None:
                expiry_date = self.entry_symbol.ID.Date.date()
                if current_date >= expiry_date:
                    self.expiration_block_date = current_date
                    self._cancel_entry_if_open()

    def _submit_exit(self, reason: str):
        if self.held_symbol is None:
            return

        quantity = self.Portfolio[self.held_symbol].Quantity
        if quantity == 0:
            return

        if self.exit_ticket is not None and self._ticket_is_open(self.exit_ticket):
            self.exit_ticket.Cancel("Replacing open exit order")

        self.exit_ticket = self.MarketOrder(
            self.held_symbol,
            -quantity
        )
        self.Debug("Submitted exit: {}".format(reason))

    def _find_contract(self, slice: Slice, symbol: Symbol):
        for chain in slice.OptionChains:
            contract = chain.Contracts.get(symbol)
            if contract is not None:
                return contract
        return None

    def _cancel_entry_if_open(self):
        if self.entry_ticket is not None and self._ticket_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")

    def _ticket_is_open(self, ticket):
        return ticket is not None and ticket.Status in (
            OrderStatus.New,
            OrderStatus.Submitted,
            OrderStatus.PartiallyFilled
        )

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        while not self.Securities[self.spy].Exchange.Hours.IsDateOpen(candidate):
            candidate -= timedelta(days=1)
        return candidate

    def OnOrderEvent(self, order_event: OrderEvent):
        if (
            self.entry_ticket is not None
            and order_event.OrderId == self.entry_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled and order_event.FillQuantity > 0:
                self.held_symbol = self.entry_symbol
                self.entry_price = float(order_event.FillPrice)
                self.time_stop_date = None

                self.Debug(
                    "Entry filled: {} at {}".format(
                        self.held_symbol, self.entry_price
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.entry_ticket = None
                self.entry_symbol = None

        if (
            self.exit_ticket is not None
            and order_event.OrderId == self.exit_ticket.OrderId
        ):
            if order_event.Status == OrderStatus.Filled:
                self.Debug(
                    "Exit filled: {} at {}".format(
                        self.held_symbol, order_event.FillPrice
                    )
                )
                self.held_symbol = None
                self.entry_price = None
                self.entry_symbol = None
                self.exit_ticket = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid
            ):
                self.exit_ticket = None

        order_type = str(order_event.OrderType)
        if "Exercise" in order_type or "Assignment" in order_type:
            self.Debug(
                "Unexpected option exercise or assignment: {}".format(order_event)
            )

    def OnAssignmentOrder(self, assignment_event):
        self.Debug(
            "Unexpected option assignment received: {}".format(assignment_event)
        )

