            .IncludeWeeklys()
            .Strikes(-100, 100)
            .Expiration(0, 365)
        )

        self.fast_closes = []
        self.slow_closes = []

        self.bucket_start = None
        self.bucket_expected_time = None
        self.bucket_closes = []

        self.entry_ticket = None
        self.entry_order_id = None
        self.entry_symbol = None
        self.entry_price = None

        self.exit_ticket = None
        self.exit_order_id = None

        self.processed_date = None
        self.no_entry_today = False

    def OnData(self, slice: Slice):
        today = self.Time.date()

        if self.processed_date != today:
            self.processed_date = today
            self.no_entry_today = False
            self._process_expiration_day(today)

        self._evaluate_exit(slice)

        if self.spy.Symbol in slice.Bars:
            self._process_minute_bar(slice.Bars[self.spy.Symbol], slice)

    def _process_minute_bar(self, minute_bar: TradeBar, slice: Slice):
        bar_time = minute_bar.Time
        local_time = bar_time.time()

        if local_time < time_from_string("09:30") or local_time >= time_from_string("16:00"):
            self._discard_bucket()
            return

        bucket_minute = (bar_time.minute // 5) * 5
        bucket_start = bar_time.replace(
            minute=bucket_minute,
            second=0,
            microsecond=0
        )

        if self.bucket_start is None:
            self._start_bucket(bucket_start, bar_time, minute_bar.Close)
            return

        same_bucket = bucket_start == self.bucket_start
        contiguous = bar_time == self.bucket_expected_time

        if not same_bucket or not contiguous:
            self._finish_bucket(slice)

            if local_time < time_from_string("16:00"):
                self._start_bucket(bucket_start, bar_time, minute_bar.Close)
            else:
                self._discard_bucket()
            return

        self.bucket_closes.append(minute_bar.Close)
        self.bucket_expected_time = bar_time + timedelta(minutes=1)

    def _start_bucket(self, bucket_start, bar_time, close):
        self.bucket_start = bucket_start
        self.bucket_expected_time = bar_time + timedelta(minutes=1)
        self.bucket_closes = [close]

    def _discard_bucket(self):
        self.bucket_start = None
        self.bucket_expected_time = None
        self.bucket_closes = []

    def _finish_bucket(self, slice: Slice):
        if self.bucket_start is None:
            return

        closes = self.bucket_closes
        bucket_start = self.bucket_start
        self._discard_bucket()

        if len(closes) != 5:
            return

        close = closes[-1]
        bar_end = bucket_start + timedelta(minutes=5)

        previous_fast = None
        previous_slow = None
        if len(self.slow_closes) >= 20:
            previous_fast = sum(self.slow_closes[-5:]) / 5.0
            previous_slow = sum(self.slow_closes[-20:]) / 20.0

        self.slow_closes.append(close)
        if len(self.slow_closes) > 20:
            self.slow_closes.pop(0)

        if len(self.slow_closes) < 20:
            return

        current_fast = sum(self.slow_closes[-5:]) / 5.0
        current_slow = sum(self.slow_closes[-20:]) / 20.0

        crossover = (
            previous_fast is not None
            and previous_slow is not None
            and previous_fast <= previous_slow
            and current_fast > current_slow
        )

        end_time = bar_end.time()
        eligible_time = (
            time_from_string("09:45")
            <= end_time
            <= time_from_string("14:30")
        )

        if crossover and eligible_time:
            self._try_enter(slice, close)

    def _try_enter(self, slice: Slice, spy_price: float):
        if self.no_entry_today:
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            return

        if self.entry_symbol is not None:
            holding = self.Portfolio[self.entry_symbol]
            if holding.Invested:
                return

        chains = []
        for item in slice.OptionChains:
            chain = item.Value if hasattr(item, "Value") else item
            chains.append(chain)

        if not chains:
            self.Debug("Skipped entry: no option chain in current Slice.")
            return

        contracts = []
        for chain in chains:
            for contract in chain:
                contracts.append(contract)

        current_date = self.Time.date()
        minimum_expiry = current_date + timedelta(days=7)

        expirations = sorted({
            contract.Expiry.date()
            for contract in contracts
            if contract.Expiry.date() >= minimum_expiry
        })

        if not expirations:
            self.Debug("Skipped entry: no expiration at least 7 days away.")
            return

        selected_expiry = expirations[0]
        minimum_strike = 1.01 * spy_price

        candidates = [
            contract for contract in contracts
            if contract.Expiry.date() == selected_expiry
            and contract.Right == OptionRight.Call
            and contract.Strike >= minimum_strike
        ]

        if not candidates:
            self.Debug("Skipped entry: no qualifying call contract.")
            return

        selected = min(
            candidates,
            key=lambda contract: (contract.Strike, str(contract.Symbol))
        )

        self.entry_symbol = selected.Symbol
        self.entry_price = None

        self.entry_ticket = self.MarketOrder(
            selected.Symbol,
            1,
            tag="SPY bullish five-minute crossover entry"
        )
        self.entry_order_id = self.entry_ticket.OrderId

        self.Debug(
            "Submitted entry: {0}, strike {1}, expiry {2}".format(
                selected.Symbol,
                selected.Strike,
                selected.Expiry.date()
            )
        )

    def _evaluate_exit(self, slice: Slice):
        if self.entry_symbol is None:
            return

        holding = self.Portfolio[self.entry_symbol]
        if not holding.Invested:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        expiry_date = self._get_expiry_date(self.entry_symbol)
        today = self.Time.date()

        if expiry_date is None:
            return

        if today == expiry_date:
            self._submit_exit("expiration-day liquidation")
            return

        previous_trading_day = self._previous_trading_day(expiry_date)
        if (
            today == previous_trading_day
            and self.Time.time() >= time_from_string("15:45")
        ):
            self._submit_exit("pre-expiration time stop")
            return

        if self.entry_price is None:
            return

        contract = self._find_contract(slice, self.entry_symbol)
        if contract is None:
            return

        bid = contract.BidPrice
        ask = contract.AskPrice

        if bid is None or ask is None or bid <= 0 or ask <= 0:
            return

        midpoint = (bid + ask) / 2.0
        if midpoint >= 1.50 * self.entry_price:
            self._submit_exit("50 percent profit target")

    def _submit_exit(self, tag: str):
        if self.entry_symbol is None:
            return

        if self.exit_ticket is not None and self._order_is_open(self.exit_ticket):
            return

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Exit required before entry fill")

        quantity = -self.Portfolio[self.entry_symbol].Quantity
        if quantity == 0:
            return

        self.exit_ticket = self.MarketOrder(self.entry_symbol, quantity, tag=tag)
        self.exit_order_id = self.exit_ticket.OrderId
        self.Debug("Submitted exit: {0}".format(tag))

    def OnOrderEvent(self, order_event: OrderEvent):
        message = str(order_event.Message or "").lower()
        if "assignment" in message or "exercise" in message:
            self.Debug(
                "Unexpected option exercise or assignment: {0}".format(
                    order_event.Message
                )
            )

        if self.entry_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.entry_price = order_event.FillPrice
                self.Debug(
                    "Entry filled: {0} at {1}".format(
                        order_event.Symbol,
                        order_event.FillPrice
                    )
                )
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_price = None
            return

        if self.exit_order_id == order_event.OrderId:
            if order_event.Status == OrderStatus.Filled:
                self.Debug("Exit filled: {0}".format(order_event.Symbol))
                self.exit_ticket = None
                self.exit_order_id = None
                self.entry_ticket = None
                self.entry_order_id = None
                self.entry_symbol = None
                self.entry_price = None
            elif order_event.Status in (
                OrderStatus.Canceled,
                OrderStatus.Invalid,
                OrderStatus.None
            ):
                self.exit_ticket = None
                self.exit_order_id = None

    def _process_expiration_day(self, today):
        if self.entry_symbol is None:
            return

        expiry_date = self._get_expiry_date(self.entry_symbol)
        if expiry_date != today:
            return

        self.no_entry_today = True

        if self.entry_ticket is not None and self._order_is_open(self.entry_ticket):
            self.entry_ticket.Cancel("Expiration processing")

        if self.Portfolio[self.entry_symbol].Invested:
            self._submit_exit("expiration processing liquidation")

    def _find_contract(self, slice: Slice, symbol: Symbol):
        for item in slice.OptionChains:
            chain = item.Value if hasattr(item, "Value") else item
            for contract in chain:
                if contract.Symbol == symbol:
                    return contract
        return None

    def _get_expiry_date(self, symbol: Symbol):
        try:
            return symbol.ID.Date.date()
        except Exception:
            return None

    def _previous_trading_day(self, date):
        candidate = date - timedelta(days=1)
        hours = self.Securities[self.spy.Symbol].Exchange.Hours

        while True:
            try:
                if hours.IsDateOpen(candidate):
                    return candidate
            except Exception:
                if candidate.weekday() < 5:
                    return candidate

            candidate -= timedelta(days=1)

    def _order_is_open(self, ticket):
        return ticket is not None and ticket.Status not in (
            OrderStatus.Filled,
            OrderStatus.Canceled,
            OrderStatus.Invalid
        )


def time_from_string(value):
    hour, minute = [int(part) for part in value.split(":")]
    from datetime import time
    return time(hour, minute)

